#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct HandoffScopeFields {
    session_id: SessionId,
    session_lifecycle_state: SessionLifecycleState,
    session_diff_id: Option<SessionDiffId>,
    focus_entity_id: Option<EntityId>,
}

fn run_handoff(command: HandoffCommand) -> Result<String> {
    match command {
        HandoffCommand::Create {
            store,
            branch,
            head,
            session,
            statement,
            session_diff,
            focus,
            expected_session_diff,
            expected_focus,
        } => {
            let mut engine = Engine::open(store)?;
            let branch_id = BranchId::parse_canonical(&branch)?;
            let head_id = CommitId::parse_canonical(&head)?;
            let session_id = SessionId::parse_canonical(&session)?;
            let session_snapshot = engine.session_snapshot(session_id)?;
            if let Some(active_branch_id) = session_snapshot.active_branch_id
                && active_branch_id != branch_id
            {
                return Err(WorkVcsError::SessionInvalid(format!(
                    "active session {session_id} is on branch {active_branch_id}, not {branch_id}"
                )));
            }
            let session_diff_id = match session_diff {
                Some(session_diff) => {
                    let session_diff_id = SessionDiffId::parse_canonical(&session_diff)?;
                    let diff = engine.session_diff(session_diff_id)?;
                    if diff.session_id != session_id {
                        return Err(WorkVcsError::SessionInvalid(format!(
                            "session diff {session_diff_id} belongs to session {}, not {session_id}",
                            diff.session_id
                        )));
                    }
                    Some(session_diff_id)
                }
                None => session_snapshot.session_diff_id,
            };
            let focus_entity_id = match focus {
                Some(focus) => Some(EntityId::parse_canonical(&focus)?),
                None => session_snapshot
                    .focus
                    .as_ref()
                    .map(|focus| focus.focus_entity_id),
            };
            let fields = HandoffScopeFields {
                session_id,
                session_lifecycle_state: session_snapshot.lifecycle_state,
                session_diff_id,
                focus_entity_id,
            };
            let scope = handoff_scope_value(fields)?;
            let record = engine.create_record(
                RecordCreateOptions::handoff(branch_id, head_id, statement)?
                    .with_scope(scope.clone())?,
            )?;
            let session_diff_snapshot = session_diff_id
                .map(|session_diff_id| engine.session_diff(session_diff_id))
                .transpose()?;
            let mut output =
                render_handoff_create(&record, &scope, session_diff_snapshot.as_ref())?;
            append_handoff_scope_expectations(
                &mut output,
                &fields,
                None,
                expected_session_diff,
                expected_focus,
            )?;
            Ok(output)
        }
        HandoffCommand::Show {
            store,
            branch,
            commit,
            handoff,
            expected_session,
            expected_session_diff,
            expected_focus,
        } => {
            let engine = Engine::open(store)?;
            let commit_id = resolve_task_query_commit(&engine, branch, commit)?;
            let record = engine.record_at(commit_id, EntityId::parse_canonical(&handoff)?)?;
            if record.state.kind != RecordKind::Handoff {
                return Err(WorkVcsError::RecordInvalid(format!(
                    "record {} is {}, not handoff",
                    record.record_entity_id, record.state.kind
                )));
            }
            let fields = parse_handoff_scope(&record.state.scope)?;
            let session_diff_snapshot = match fields.and_then(|fields| fields.session_diff_id) {
                Some(session_diff_id) => {
                    let diff = engine.session_diff(session_diff_id)?;
                    if let Some(fields) = fields
                        && diff.session_id != fields.session_id
                    {
                        return Err(WorkVcsError::SessionInvalid(format!(
                            "session diff {session_diff_id} belongs to session {}, not {}",
                            diff.session_id, fields.session_id
                        )));
                    }
                    Some(diff)
                }
                None => None,
            };
            let mut output =
                render_handoff_show(&record, fields.as_ref(), session_diff_snapshot.as_ref())?;
            if let Some(fields) = fields.as_ref() {
                append_handoff_scope_expectations(
                    &mut output,
                    fields,
                    expected_session,
                    expected_session_diff,
                    expected_focus,
                )?;
            } else if expected_session.is_some()
                || expected_session_diff.is_some()
                || expected_focus.is_some()
            {
                return Err(WorkVcsError::RecordInvalid(
                    "handoff scope is not a recognized focused handoff scope".to_owned(),
                ));
            }
            Ok(output)
        }
        HandoffCommand::Consume {
            store,
            branch,
            commit,
            handoff,
            session,
            expected_source_session,
            expected_session_diff,
            expected_focus,
            expected_session,
            expected_lifecycle_state,
        } => {
            let mut engine = Engine::open(store)?;
            let commit_id = resolve_task_query_commit(&engine, branch, commit)?;
            let record = engine.record_at(commit_id, EntityId::parse_canonical(&handoff)?)?;
            if record.state.kind != RecordKind::Handoff {
                return Err(WorkVcsError::RecordInvalid(format!(
                    "record {} is {}, not handoff",
                    record.record_entity_id, record.state.kind
                )));
            }
            let fields = parse_handoff_scope(&record.state.scope)?.ok_or_else(|| {
                WorkVcsError::RecordInvalid(
                    "handoff scope is not a recognized focused handoff scope".to_owned(),
                )
            })?;
            let focus_entity_id = fields.focus_entity_id.ok_or_else(|| {
                WorkVcsError::RecordInvalid(
                    "focused handoff scope does not contain a focus entity".to_owned(),
                )
            })?;
            let session_diff_snapshot = match fields.session_diff_id {
                Some(session_diff_id) => {
                    let diff = engine.session_diff(session_diff_id)?;
                    if diff.session_id != fields.session_id {
                        return Err(WorkVcsError::SessionInvalid(format!(
                            "session diff {session_diff_id} belongs to session {}, not {}",
                            diff.session_id, fields.session_id
                        )));
                    }
                    Some(diff)
                }
                None => None,
            };
            let mut source_expectation_output = String::new();
            append_handoff_consume_source_expectations(
                &mut source_expectation_output,
                &fields,
                expected_source_session,
                expected_session_diff,
                expected_focus,
            )?;
            let consumed = engine.set_session_focus(SessionFocusOptions::new(
                SessionId::parse_canonical(&session)?,
                focus_entity_id,
            ))?;
            let mut output = render_handoff_consume(
                &record,
                &fields,
                session_diff_snapshot.as_ref(),
                &consumed,
            )?;
            output.push_str(&source_expectation_output);
            append_handoff_consume_expectations(
                &mut output,
                &consumed,
                expected_session,
                expected_lifecycle_state,
            )?;
            Ok(output)
        }
    }
}

fn run_verify(args: Vec<String>) -> Result<String> {
    let args = match VerifyArgs::try_parse_from(
        std::iter::once(String::from("workvcs verify")).chain(args),
    ) {
        Ok(args) => args,
        Err(error)
            if matches!(
                error.kind(),
                ErrorKind::DisplayHelp | ErrorKind::DisplayVersion
            ) =>
        {
            return Ok(error.to_string());
        }
        Err(error) => {
            return Err(WorkVcsError::QueryInvalid(format!(
                "verify arguments invalid: {error}"
            )));
        }
    };
    let VerifyArgs {
        store,
        branch,
        head,
        result,
        method,
        source_session,
        evidence_kind,
        evidence_metadata_json,
        evidence_content_role,
        evidence_content,
        evidence_content_digest,
        evidence_content_file,
        evidence_content_size_bytes,
        evidence_media_type,
        evidence_format_metadata_json,
        acceptance_criterion,
        verification_requirement,
        resource,
        adapter_kind,
        adapter_schema_version,
        scope_kind,
        scope_schema_version,
        scope_payload_json,
        scope_path,
        scope_path_prefix,
        scope_glob,
        scope_git_worktree,
        resource_fingerprint,
        resource_content,
        resource_content_file,
        resource_content_from_scope_path,
        resource_content_from_scope_path_prefix,
        resource_content_from_scope_glob,
        resource_content_from_scope_git_worktree,
        resource_summary_json,
        resource_detail_content,
        resource_detail_content_file,
        resource_detail_content_digest,
        resource_detail_content_size_bytes,
        resource_detail_media_type,
        resource_detail_format_metadata_json,
        cache_detail_json,
        expected_branch,
        expected_head,
        expected_target_kind,
        expected_target,
        expected_result,
        expected_evidence_kind,
        expected_evidence_relations,
        expected_resource_basis,
        expected_cache_applicability,
        expected_cache_reason_code,
    } = args;
    let mut engine = Engine::open(store)?;
    let source_session_id = source_session
        .as_deref()
        .map(SessionId::parse_canonical)
        .transpose()?;
    let target = verification_target_from_cli(acceptance_criterion, verification_requirement)?;
    let mut evidence = EvidenceCreateOptions::new(
        evidence_kind,
        parse_cli_object("verify evidence metadata", &evidence_metadata_json)?,
    )?;
    if let Some(source_session_id) = source_session_id {
        evidence = evidence.with_source_session_id(source_session_id);
    }
    if let Some(content) = evidence_content_from_cli(EvidenceContentArgs {
        role: evidence_content_role,
        role_label: "--evidence-content-role",
        content: evidence_content,
        content_digest: evidence_content_digest,
        content_file: evidence_content_file,
        content_size_bytes: evidence_content_size_bytes,
        media_type: evidence_media_type,
        format_metadata_json: evidence_format_metadata_json,
        content_error_message: "evidence content requires exactly one of --evidence-content, --evidence-content-file, or --evidence-content-digest with --evidence-content-size-bytes",
    })? {
        evidence = evidence.with_contents(vec![content])?;
    }
    let mut options = VerifyOptions::new(
        BranchId::parse_canonical(&branch)?,
        CommitId::parse_canonical(&head)?,
        target,
        parse_verification_result(&result)?,
        evidence,
    )?;
    if let Some(method) = method {
        options = options.with_method(method_value(&method))?;
    }
    let resource_observation = verify_resource_observation_from_cli(
        VerifyResourceObservationArgs {
            resource,
            adapter_kind,
            adapter_schema_version,
            scope_kind,
            scope_schema_version,
            scope_payload_json,
            scope_path,
            scope_path_prefix,
            scope_glob,
            scope_git_worktree,
            resource_fingerprint,
            resource_content,
            resource_content_file,
            resource_content_from_scope_path,
            resource_content_from_scope_path_prefix,
            resource_content_from_scope_glob,
            resource_content_from_scope_git_worktree,
            resource_summary_json,
            resource_detail_content,
            resource_detail_content_file,
            resource_detail_content_digest,
            resource_detail_content_size_bytes,
            resource_detail_media_type,
            resource_detail_format_metadata_json,
        },
        source_session_id,
    )?;
    if resource_observation.is_none() && cache_detail_json != "{}" {
        return Err(WorkVcsError::TaskInvalid(
            "--cache-detail-json requires resource observation inputs".to_owned(),
        ));
    }
    if let Some(resource_observation) = resource_observation {
        options = options.with_resource_observation(resource_observation);
    }
    options =
        options.with_cache_detail(parse_cli_object("verify cache detail", &cache_detail_json)?)?;
    let result = engine.verify(options)?;
    let mut output = render_verify_result(&result)?;
    append_verify_expectations(
        &mut output,
        &result,
        VerifyExpectationArgs {
            expected_branch,
            expected_head,
            expected_target_kind,
            expected_target,
            expected_result,
            expected_evidence_kind,
            expected_evidence_relations,
            expected_resource_basis,
            expected_cache_applicability,
            expected_cache_reason_code,
        },
    )?;
    Ok(output)
}

fn parse_task_status(value: &str) -> Result<TaskStatus> {
    match value {
        "pending" => Ok(TaskStatus::Pending),
        "in_progress" => Ok(TaskStatus::InProgress),
        "blocked" => Ok(TaskStatus::Blocked),
        "done" => Ok(TaskStatus::Done),
        "failed" => Ok(TaskStatus::Failed),
        "cancelled" => Ok(TaskStatus::Cancelled),
        other => Err(WorkVcsError::TaskInvalid(format!(
            "task status {other:?} is not in the CLI vocabulary"
        ))),
    }
}

fn parse_context_profile(value: &str) -> Result<ContextProfile> {
    match value {
        "brief" => Ok(ContextProfile::Brief),
        "normal" => Ok(ContextProfile::Normal),
        "full" => Ok(ContextProfile::Full),
        other => Err(WorkVcsError::QueryInvalid(format!(
            "context profile {other:?} is not in the CLI vocabulary"
        ))),
    }
}

fn context_packet_options_from_cli(
    session_id: SessionId,
    profile: Option<String>,
    budget_items: Option<usize>,
    scope: Option<CanonicalValue>,
) -> Result<ContextPacketOptions> {
    let mut options = ContextPacketOptions::new(session_id);
    if let Some(profile) = profile {
        options = options.with_profile(parse_context_profile(&profile)?);
    }
    if let Some(budget_items) = budget_items {
        options = options.with_budget_items(budget_items)?;
    }
    if let Some(scope) = scope {
        options = options.with_scope(scope)?;
    }
    Ok(options)
}

