fn parse_claim_guard_reason(value: &str) -> Result<ClaimGuardReason> {
    match value {
        "unclaimed" => Ok(ClaimGuardReason::Unclaimed),
        "owned_exclusive_claim" => Ok(ClaimGuardReason::OwnedExclusiveClaim),
        "unique_shared_claimant" => Ok(ClaimGuardReason::UniqueSharedClaimant),
        "exclusive_claim_owned_by_other_session" => {
            Ok(ClaimGuardReason::ExclusiveClaimOwnedByOtherSession)
        }
        "shared_claim_set_does_not_include_session" => {
            Ok(ClaimGuardReason::SharedClaimSetDoesNotIncludeSession)
        }
        "non_unique_shared_claim_set" => Ok(ClaimGuardReason::NonUniqueSharedClaimSet),
        other => Err(WorkVcsError::ClaimInvalid(format!(
            "claim guard reason {other:?} is not supported"
        ))),
    }
}

fn parse_cli_object(label: &str, json: &str) -> Result<CanonicalValue> {
    let value = parse_canonical_json(json.as_bytes())?;
    if matches!(value, CanonicalValue::Object(_)) {
        Ok(value)
    } else {
        Err(WorkVcsError::TaskInvalid(format!(
            "{label} must be an object"
        )))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CliScopeSource {
    Json,
    Path,
    PathPrefix,
    Glob,
    GitWorktree,
}

#[derive(Debug)]
struct CliScope {
    value: CanonicalValue,
    source: CliScopeSource,
}

impl CliScope {
    fn into_value(self) -> CanonicalValue {
        self.value
    }

    fn default_scope_kind(&self) -> Option<&'static str> {
        match self.source {
            CliScopeSource::Json => None,
            CliScopeSource::Path | CliScopeSource::PathPrefix | CliScopeSource::Glob => {
                Some("path")
            }
            CliScopeSource::GitWorktree => Some("git-worktree"),
        }
    }
}

fn scope_from_cli(
    label: &str,
    json_flag: &str,
    path_flag: &str,
    prefix_flag: &str,
    scope_json: Option<String>,
    scope_path: Option<PathBuf>,
    scope_path_prefix: Option<PathBuf>,
) -> Result<Option<CliScope>> {
    let sources = usize::from(scope_json.is_some())
        + usize::from(scope_path.is_some())
        + usize::from(scope_path_prefix.is_some());
    if sources > 1 {
        return Err(WorkVcsError::QueryInvalid(format!(
            "{label} requires at most one of {json_flag}, {path_flag}, or {prefix_flag}"
        )));
    }

    if let Some(scope_json) = scope_json {
        return Ok(Some(CliScope {
            value: parse_cli_object(label, &scope_json)?,
            source: CliScopeSource::Json,
        }));
    }
    if let Some(path) = scope_path {
        return Ok(Some(CliScope {
            value: path_scope_value("path", path)?,
            source: CliScopeSource::Path,
        }));
    }
    if let Some(path_prefix) = scope_path_prefix {
        return Ok(Some(CliScope {
            value: path_scope_value("path_prefix", path_prefix)?,
            source: CliScopeSource::PathPrefix,
        }));
    }
    Ok(None)
}

fn path_scope_value(key: &str, path: PathBuf) -> Result<CanonicalValue> {
    CanonicalValue::object(vec![(
        key.to_owned(),
        CanonicalValue::String(normalize_cli_scope_path(path)?),
    )])
}

fn glob_scope_value(glob: String) -> Result<CanonicalValue> {
    let scope = local_file_glob_scope_from_pattern(&glob)?;
    CanonicalValue::object(vec![(
        "glob".to_owned(),
        CanonicalValue::String(scope.pattern),
    )])
}

fn git_worktree_scope_value(repo: PathBuf) -> Result<CanonicalValue> {
    CanonicalValue::object(vec![(
        "repo".to_owned(),
        CanonicalValue::String(normalize_cli_scope_path(repo)?),
    )])
}

fn verify_resource_scope_from_cli(
    scope_json: Option<String>,
    scope_path: Option<PathBuf>,
    scope_path_prefix: Option<PathBuf>,
    scope_glob: Option<String>,
    scope_git_worktree: Option<PathBuf>,
) -> Result<Option<CliScope>> {
    let sources = usize::from(scope_json.is_some())
        + usize::from(scope_path.is_some())
        + usize::from(scope_path_prefix.is_some())
        + usize::from(scope_glob.is_some())
        + usize::from(scope_git_worktree.is_some());
    if sources > 1 {
        return Err(WorkVcsError::QueryInvalid(
            "verify resource scope payload requires at most one of --scope-payload-json, --scope-path, --scope-path-prefix, --scope-glob, or --scope-git-worktree".to_owned(),
        ));
    }
    if let Some(scope_json) = scope_json {
        return Ok(Some(CliScope {
            value: parse_cli_object("verify resource scope payload", &scope_json)?,
            source: CliScopeSource::Json,
        }));
    }
    if let Some(path) = scope_path {
        return Ok(Some(CliScope {
            value: path_scope_value("path", path)?,
            source: CliScopeSource::Path,
        }));
    }
    if let Some(path_prefix) = scope_path_prefix {
        return Ok(Some(CliScope {
            value: path_scope_value("path_prefix", path_prefix)?,
            source: CliScopeSource::PathPrefix,
        }));
    }
    if let Some(glob) = scope_glob {
        return Ok(Some(CliScope {
            value: glob_scope_value(glob)?,
            source: CliScopeSource::Glob,
        }));
    }
    if let Some(repo) = scope_git_worktree {
        return Ok(Some(CliScope {
            value: git_worktree_scope_value(repo)?,
            source: CliScopeSource::GitWorktree,
        }));
    }
    Ok(None)
}

fn normalize_cli_scope_path(path: PathBuf) -> Result<String> {
    normalize_cli_scope_path_components(&path)
}

fn normalize_cli_scope_glob(pattern: &str) -> Result<String> {
    normalize_cli_scope_path_components(Path::new(pattern))
}

fn normalize_cli_scope_path_components(path: &Path) -> Result<String> {
    let mut prefix = None;
    let mut rooted = false;
    let mut segments: Vec<String> = Vec::new();
    for component in path.components() {
        match component {
            Component::Prefix(path_prefix) => {
                let text = path_prefix.as_os_str().to_str().ok_or_else(|| {
                    WorkVcsError::QueryInvalid("scope path prefix must be valid UTF-8".to_owned())
                })?;
                prefix = Some(text.replace('\\', "/"));
            }
            Component::RootDir => {
                rooted = true;
            }
            Component::CurDir => {}
            Component::ParentDir => match segments.last() {
                Some(last) if last != ".." => {
                    segments.pop();
                }
                _ if !rooted => segments.push("..".to_owned()),
                _ => {}
            },
            Component::Normal(segment) => {
                let text = segment.to_str().ok_or_else(|| {
                    WorkVcsError::QueryInvalid("scope path must be valid UTF-8".to_owned())
                })?;
                segments.push(text.to_owned());
            }
        }
    }

    let body = segments.join("/");
    Ok(match (prefix, rooted, body.is_empty()) {
        (Some(prefix), true, true) => format!("{prefix}/"),
        (Some(prefix), true, false) => format!("{prefix}/{body}"),
        (Some(prefix), false, true) => prefix,
        (Some(prefix), false, false) => format!("{prefix}/{body}"),
        (None, true, true) => "/".to_owned(),
        (None, true, false) => format!("/{body}"),
        (None, false, true) => ".".to_owned(),
        (None, false, false) => body,
    })
}

fn canonical_json_input_bytes(
    label: &str,
    json: Option<String>,
    json_file: Option<PathBuf>,
) -> Result<Vec<u8>> {
    match (json, json_file) {
        (Some(json), None) => Ok(json.into_bytes()),
        (None, Some(path)) => read_cli_file(label, &path),
        _ => Err(WorkVcsError::QueryInvalid(format!(
            "{label} requires exactly one of --json or --json-file"
        ))),
    }
}

fn render_canonical_encode(json: &[u8], expected_canonical_json: Option<String>) -> Result<String> {
    let value = parse_canonical_json(json)?;
    let canonical_json = canonical_cli_json("canonical JSON", &value)?;
    let matches_expected = if let Some(expected_canonical_json) = expected_canonical_json {
        if canonical_json != expected_canonical_json {
            return Err(WorkVcsError::CanonicalEncodingInvalid(format!(
                "canonical JSON {canonical_json:?} does not match expected {expected_canonical_json:?}"
            )));
        }
        "\nmatches_expected=true"
    } else {
        ""
    };
    Ok(format!(
        "canonical_json={canonical_json}\nsize_bytes={}{}\n",
        canonical_json.len(),
        matches_expected
    ))
}

fn render_canonical_digest(
    domain: &str,
    json: &[u8],
    expected_digest: Option<String>,
) -> Result<String> {
    let value = parse_canonical_json(json)?;
    let canonical_json = canonical_cli_json("canonical JSON", &value)?;
    let digest = match domain {
        "entity-version" => entity_version_digest(&value)?,
        "relation-version" => relation_version_digest(&value)?,
        other => {
            return Err(WorkVcsError::DigestInvalid(format!(
                "canonical digest domain {other:?} is not supported"
            )));
        }
    };
    let matches_expected = if let Some(expected_digest) = expected_digest {
        let expected_digest = Digest::from_hex(&expected_digest)?;
        if digest != expected_digest {
            return Err(WorkVcsError::DigestInvalid(format!(
                "canonical {domain} digest {digest} does not match expected {expected_digest}"
            )));
        }
        "\nmatches_expected=true"
    } else {
        ""
    };
    Ok(format!(
        "domain={domain}\ndigest={digest}\ncanonical_json={canonical_json}\nsize_bytes={}{}\n",
        canonical_json.len(),
        matches_expected
    ))
}

const SUPPORTED_CANONICAL_DIGEST_DOMAINS: &[&str] = &["entity-version", "relation-version"];

fn render_canonical_digest_domains() -> String {
    let mut output = format!("domains={}\n", SUPPORTED_CANONICAL_DIGEST_DOMAINS.len());
    for (index, domain) in SUPPORTED_CANONICAL_DIGEST_DOMAINS.iter().enumerate() {
        writeln!(output, "domain.{index}={domain}").expect("write to String");
    }
    output
}

const CANONICAL_JSON_INPUT_MODES: &[&str] = &["--json", "--json-file"];
const CANONICAL_CONTENT_INPUT_MODES: &[&str] = &["--content", "--content-hex", "--content-file"];

fn render_canonical_input_modes() -> String {
    let mut output = format!("json_input_modes={}\n", CANONICAL_JSON_INPUT_MODES.len());
    for (index, mode) in CANONICAL_JSON_INPUT_MODES.iter().enumerate() {
        writeln!(output, "json_input_mode.{index}={mode}").expect("write to String");
    }
    writeln!(
        output,
        "content_input_modes={}",
        CANONICAL_CONTENT_INPUT_MODES.len()
    )
    .expect("write to String");
    for (index, mode) in CANONICAL_CONTENT_INPUT_MODES.iter().enumerate() {
        writeln!(output, "content_input_mode.{index}={mode}").expect("write to String");
    }
    output
}

fn render_content_digest(
    content: Option<String>,
    content_hex: Option<String>,
    content_file: Option<PathBuf>,
    expected_digest: Option<String>,
) -> Result<String> {
    let bytes = match (content, content_hex, content_file) {
        (Some(content), None, None) => content.into_bytes(),
        (None, Some(content_hex), None) => hex::decode(&content_hex).map_err(|error| {
            WorkVcsError::DigestInvalid(format!("content hex decode failed: {error}"))
        })?,
        (None, None, Some(path)) => read_cli_file("canonical content", &path)?,
        _ => {
            return Err(WorkVcsError::DigestInvalid(
                "content digest requires exactly one of --content, --content-hex, or --content-file"
                    .to_owned(),
            ));
        }
    };
    let digest = content_object_digest(&bytes);
    let matches_expected = if let Some(expected_digest) = expected_digest {
        let expected_digest = Digest::from_hex(&expected_digest)?;
        if digest != expected_digest {
            return Err(WorkVcsError::DigestInvalid(format!(
                "content digest {digest} does not match expected {expected_digest}"
            )));
        }
        "\nmatches_expected=true"
    } else {
        ""
    };
    Ok(format!(
        "content_digest={digest}\nsize_bytes={}{}\n",
        bytes.len(),
        matches_expected
    ))
}

fn render_validate_digest(digest: &str) -> Result<String> {
    let digest = Digest::from_hex(digest)?;
    Ok(format!("digest={digest}\nvalid=true\n"))
}

fn read_cli_file(label: &str, path: &Path) -> Result<Vec<u8>> {
    fs::read(path).map_err(|error| {
        WorkVcsError::QueryInvalid(format!(
            "failed to read {label} file {}: {error}",
            path.display()
        ))
    })
}

