fn render_work_state_mapping_digest(
    entity_mappings: Vec<String>,
    relation_mappings: Vec<String>,
    expected_digest: Option<String>,
) -> Result<String> {
    let entities = entity_mappings
        .iter()
        .map(|mapping| parse_work_state_entity_mapping(mapping))
        .collect::<Result<Vec<_>>>()?;
    let relations = relation_mappings
        .iter()
        .map(|mapping| parse_work_state_relation_mapping(mapping))
        .collect::<Result<Vec<_>>>()?;
    let state = WorkState::new(entities, relations)?;
    let digest = work_state_mapping_digest(&state);
    let matches_expected = if let Some(expected_digest) = expected_digest {
        let expected_digest = Digest::from_hex(&expected_digest)?;
        if digest != expected_digest {
            return Err(WorkVcsError::DigestInvalid(format!(
                "work state digest {digest} does not match expected {expected_digest}"
            )));
        }
        "\nmatches_expected=true"
    } else {
        ""
    };
    Ok(format!(
        "work_state_digest={digest}\nentities={}\nrelations={}{}\n",
        state.entities().len(),
        state.relations().len(),
        matches_expected
    ))
}

fn parse_work_state_entity_mapping(value: &str) -> Result<(EntityId, EntityVersionId)> {
    let (entity_id, version_id) = split_work_state_mapping("entity", value)?;
    Ok((
        EntityId::parse_canonical(entity_id)?,
        EntityVersionId::parse_canonical(version_id)?,
    ))
}

fn parse_work_state_relation_mapping(value: &str) -> Result<(RelationId, RelationVersionId)> {
    let (relation_id, version_id) = split_work_state_mapping("relation", value)?;
    Ok((
        RelationId::parse_canonical(relation_id)?,
        RelationVersionId::parse_canonical(version_id)?,
    ))
}

fn split_work_state_mapping<'a>(label: &str, value: &'a str) -> Result<(&'a str, &'a str)> {
    let (subject, version) = value.split_once('=').ok_or_else(|| {
        WorkVcsError::CanonicalEncodingInvalid(format!(
            "{label} mapping must use SUBJECT_ID=VERSION_ID"
        ))
    })?;
    if subject.is_empty() || version.is_empty() || version.contains('=') {
        return Err(WorkVcsError::CanonicalEncodingInvalid(format!(
            "{label} mapping must use SUBJECT_ID=VERSION_ID"
        )));
    }
    Ok((subject, version))
}

struct EvidenceContentArgs {
    role: Option<String>,
    role_label: &'static str,
    content: Option<String>,
    content_digest: Option<String>,
    content_file: Option<PathBuf>,
    content_size_bytes: Option<i64>,
    media_type: Option<String>,
    format_metadata_json: String,
    content_error_message: &'static str,
}

fn evidence_content_from_cli(args: EvidenceContentArgs) -> Result<Option<EvidenceContentInput>> {
    let has_content_args = args.role.is_some()
        || args.content.is_some()
        || args.content_digest.is_some()
        || args.content_file.is_some()
        || args.content_size_bytes.is_some()
        || args.media_type.is_some()
        || args.format_metadata_json != "{}";
    if !has_content_args {
        return Ok(None);
    }

    let role = required_arg(args.role_label, args.role)?;
    let mut content = match (
        args.content,
        args.content_digest,
        args.content_file,
        args.content_size_bytes,
    ) {
        (Some(content), None, None, None) => {
            EvidenceContentInput::from_raw_bytes(role, content.as_bytes())?
        }
        (None, Some(content_digest), None, Some(content_size_bytes)) => {
            EvidenceContentInput::from_digest(
                role,
                Digest::from_hex(&content_digest)?,
                content_size_bytes,
            )?
        }
        (None, None, Some(path), None) => {
            let bytes = read_cli_file("evidence content", &path)?;
            EvidenceContentInput::from_raw_bytes(role, bytes)?
        }
        _ => {
            return Err(WorkVcsError::EvidenceInvalid(
                args.content_error_message.to_owned(),
            ));
        }
    };
    if let Some(media_type) = args.media_type {
        content = content.with_media_type(media_type)?;
    }
    content = content.with_format_metadata(parse_cli_object(
        "evidence content format metadata",
        &args.format_metadata_json,
    )?)?;
    Ok(Some(content))
}

struct ResourceFingerprintArgs {
    fingerprint: Option<String>,
    content: Option<String>,
    content_file: Option<PathBuf>,
    content_from_scope_path: bool,
    content_from_scope_path_prefix: bool,
    content_from_scope_glob: bool,
    content_from_scope_git_worktree: bool,
    scope_path: Option<PathBuf>,
    scope_path_prefix: Option<PathBuf>,
    scope_glob: Option<String>,
    scope_git_worktree: Option<PathBuf>,
}

#[derive(Debug)]
struct ResourceFingerprintResult {
    fingerprint: Digest,
    summary: Option<CanonicalValue>,
}

impl ResourceFingerprintResult {
    fn without_summary(fingerprint: Digest) -> Self {
        Self {
            fingerprint,
            summary: None,
        }
    }

    fn with_summary(fingerprint: Digest, summary: CanonicalValue) -> Self {
        Self {
            fingerprint,
            summary: Some(summary),
        }
    }
}

fn fingerprint_from_cli(args: ResourceFingerprintArgs) -> Result<ResourceFingerprintResult> {
    match (
        args.fingerprint,
        args.content,
        args.content_file,
        args.content_from_scope_path,
        args.content_from_scope_path_prefix,
        args.content_from_scope_glob,
        args.content_from_scope_git_worktree,
    ) {
        (Some(fingerprint), None, None, false, false, false, false) => {
            Digest::from_hex(&fingerprint).map(ResourceFingerprintResult::without_summary)
        }
        (None, Some(content), None, false, false, false, false) => Ok(
            ResourceFingerprintResult::without_summary(content_object_digest(content.as_bytes())),
        ),
        (None, None, Some(path), false, false, false, false) => {
            let bytes = read_cli_file("resource observation content", &path)?;
            Ok(ResourceFingerprintResult::without_summary(
                content_object_digest(&bytes),
            ))
        }
        (None, None, None, true, false, false, false) => {
            let path = required_arg("--scope-path", args.scope_path)?;
            let bytes = read_cli_file("resource observation content from scope path", &path)?;
            Ok(ResourceFingerprintResult::with_summary(
                content_object_digest(&bytes),
                local_file_scope_path_observation_summary(&path)?,
            ))
        }
        (None, None, None, false, true, false, false) => {
            let path_prefix = required_arg("--scope-path-prefix", args.scope_path_prefix)?;
            local_file_path_prefix_snapshot(&path_prefix)
                .map(|snapshot| {
                    ResourceFingerprintResult::with_summary(snapshot.fingerprint, snapshot.summary)
                })
                .map_err(|failure| {
                    WorkVcsError::QueryInvalid(format!(
                        "failed to read resource observation content from scope path prefix {}: {}",
                        path_prefix.display(),
                        failure.message()
                    ))
                })
        }
        (None, None, None, false, false, true, false) => {
            let glob = required_arg("--scope-glob", args.scope_glob)?;
            local_file_glob_snapshot(&glob)
                .map(|snapshot| {
                    ResourceFingerprintResult::with_summary(snapshot.fingerprint, snapshot.summary)
                })
                .map_err(|failure| {
                    WorkVcsError::QueryInvalid(format!(
                        "failed to read resource observation content from scope glob {glob:?}: {}",
                        failure.message()
                    ))
                })
        }
        (None, None, None, false, false, false, true) => {
            let repo = required_arg("--scope-git-worktree", args.scope_git_worktree)?;
            git_worktree_snapshot(&repo)
                .map(|snapshot| {
                    ResourceFingerprintResult::with_summary(snapshot.fingerprint, snapshot.summary)
                })
                .map_err(|failure| {
                    WorkVcsError::QueryInvalid(format!(
                        "failed to read resource observation content from scope git worktree {}: {}",
                        repo.display(),
                        failure.message()
                    ))
                })
        }
        _ => Err(WorkVcsError::TaskInvalid(
            "expected exactly one fingerprint source".to_owned(),
        )),
    }
}

struct ResourceObservationDetailArgs {
    content: Option<String>,
    content_file: Option<PathBuf>,
    content_digest: Option<String>,
    content_size_bytes: Option<i64>,
    media_type: Option<String>,
    format_metadata_json: String,
    detail_error_message: &'static str,
}

fn resource_observation_detail_from_cli(
    args: ResourceObservationDetailArgs,
) -> Result<Option<ResourceObservationDetailInput>> {
    let has_detail_args = args.content.is_some()
        || args.content_file.is_some()
        || args.content_digest.is_some()
        || args.content_size_bytes.is_some()
        || args.media_type.is_some()
        || args.format_metadata_json != "{}";
    if !has_detail_args {
        return Ok(None);
    }

    let mut detail = match (
        args.content,
        args.content_file,
        args.content_digest,
        args.content_size_bytes,
    ) {
        (Some(content), None, None, None) => {
            ResourceObservationDetailInput::from_raw_bytes(content.as_bytes())?
        }
        (None, Some(path), None, None) => {
            let bytes = read_cli_file("resource observation detail content", &path)?;
            ResourceObservationDetailInput::from_raw_bytes(bytes)?
        }
        (None, None, Some(content_digest), Some(content_size_bytes)) => {
            ResourceObservationDetailInput::from_digest(
                Digest::from_hex(&content_digest)?,
                content_size_bytes,
            )?
        }
        _ => {
            return Err(WorkVcsError::ResourceInvalid(
                args.detail_error_message.to_owned(),
            ));
        }
    };
    if let Some(media_type) = args.media_type {
        detail = detail.with_media_type(media_type)?;
    }
    detail = detail.with_format_metadata(parse_cli_object(
        "resource observation detail format metadata",
        &args.format_metadata_json,
    )?)?;
    Ok(Some(detail))
}

fn required_arg<T>(label: &str, value: Option<T>) -> Result<T> {
    value.ok_or_else(|| WorkVcsError::TaskInvalid(format!("{label} is required")))
}

struct ResourceBasisArgs {
    resource: Option<String>,
    adapter_kind: Option<String>,
    adapter_schema_version: Option<i64>,
    scope_kind: Option<String>,
    scope_schema_version: Option<i64>,
    scope_payload_json: Option<String>,
    baseline_fingerprint: Option<String>,
    baseline_observation: Option<String>,
}

fn resource_basis_from_cli(args: ResourceBasisArgs) -> Result<VerificationResourceBasis> {
    let mut basis = VerificationResourceBasis::new(
        ResourceId::parse_canonical(&required_arg("--resource", args.resource)?)?,
        required_arg("--adapter-kind", args.adapter_kind)?,
        required_arg("--adapter-schema-version", args.adapter_schema_version)?,
        required_arg("--scope-kind", args.scope_kind)?,
        required_arg("--scope-schema-version", args.scope_schema_version)?,
        parse_cli_object(
            "resource basis scope payload",
            &required_arg("--scope-payload-json", args.scope_payload_json)?,
        )?,
        Digest::from_hex(&required_arg(
            "--baseline-fingerprint",
            args.baseline_fingerprint,
        )?)?,
    )?;
    if let Some(baseline_observation) = args.baseline_observation {
        basis = basis.with_baseline_observation_id(ResourceObservationId::parse_canonical(
            &baseline_observation,
        )?)?;
    }
    Ok(basis)
}

struct VerifyResourceObservationArgs {
    resource: Option<String>,
    adapter_kind: Option<String>,
    adapter_schema_version: Option<i64>,
    scope_kind: Option<String>,
    scope_schema_version: Option<i64>,
    scope_payload_json: Option<String>,
    scope_path: Option<PathBuf>,
    scope_path_prefix: Option<PathBuf>,
    scope_glob: Option<String>,
    scope_git_worktree: Option<PathBuf>,
    resource_fingerprint: Option<String>,
    resource_content: Option<String>,
    resource_content_file: Option<PathBuf>,
    resource_content_from_scope_path: bool,
    resource_content_from_scope_path_prefix: bool,
    resource_content_from_scope_glob: bool,
    resource_content_from_scope_git_worktree: bool,
    resource_summary_json: String,
    resource_detail_content: Option<String>,
    resource_detail_content_file: Option<PathBuf>,
    resource_detail_content_digest: Option<String>,
    resource_detail_content_size_bytes: Option<i64>,
    resource_detail_media_type: Option<String>,
    resource_detail_format_metadata_json: String,
}

fn verify_resource_observation_from_cli(
    args: VerifyResourceObservationArgs,
    source_session_id: Option<SessionId>,
) -> Result<Option<VerifyResourceObservationInput>> {
    let uses_git_worktree_scope = args.scope_git_worktree.is_some();
    let uses_git_worktree_content = args.resource_content_from_scope_git_worktree;
    let has_resource_args = args.resource.is_some()
        || args.adapter_kind.is_some()
        || args.adapter_schema_version.is_some()
        || args.scope_kind.is_some()
        || args.scope_schema_version.is_some()
        || args.scope_payload_json.is_some()
        || args.scope_path.is_some()
        || args.scope_path_prefix.is_some()
        || args.scope_glob.is_some()
        || args.scope_git_worktree.is_some()
        || args.resource_fingerprint.is_some()
        || args.resource_content.is_some()
        || args.resource_content_file.is_some()
        || args.resource_content_from_scope_path
        || args.resource_content_from_scope_path_prefix
        || args.resource_content_from_scope_glob
        || args.resource_content_from_scope_git_worktree
        || args.resource_summary_json != "{}"
        || args.resource_detail_content.is_some()
        || args.resource_detail_content_file.is_some()
        || args.resource_detail_content_digest.is_some()
        || args.resource_detail_content_size_bytes.is_some()
        || args.resource_detail_media_type.is_some()
        || args.resource_detail_format_metadata_json != "{}";
    if !has_resource_args {
        return Ok(None);
    }

    let fingerprint = fingerprint_from_cli(ResourceFingerprintArgs {
        fingerprint: args.resource_fingerprint,
        content: args.resource_content,
        content_file: args.resource_content_file,
        content_from_scope_path: args.resource_content_from_scope_path,
        content_from_scope_path_prefix: args.resource_content_from_scope_path_prefix,
        content_from_scope_glob: args.resource_content_from_scope_glob,
        content_from_scope_git_worktree: args.resource_content_from_scope_git_worktree,
        scope_path: args.scope_path.clone(),
        scope_path_prefix: args.scope_path_prefix.clone(),
        scope_glob: args.scope_glob.clone(),
        scope_git_worktree: args.scope_git_worktree.clone(),
    })?;
    let summary = if args.resource_summary_json == "{}" {
        match fingerprint.summary {
            Some(summary) => summary,
            None => parse_cli_object(
                "verify resource observation summary",
                &args.resource_summary_json,
            )?,
        }
    } else {
        parse_cli_object(
            "verify resource observation summary",
            &args.resource_summary_json,
        )?
    };
    let resource_id = ResourceId::parse_canonical(&required_arg("--resource", args.resource)?)?;
    let adapter_kind = required_arg("--adapter-kind", args.adapter_kind)?;
    let adapter_schema_version =
        required_arg("--adapter-schema-version", args.adapter_schema_version)?;
    let mut observation = ResourceObservationCreateOptions::new(
        resource_id,
        adapter_kind.clone(),
        adapter_schema_version,
        fingerprint.fingerprint,
        summary,
    )?;
    if let Some(detail_content) = resource_observation_detail_from_cli(
        ResourceObservationDetailArgs {
            content: args.resource_detail_content,
            content_file: args.resource_detail_content_file,
            content_digest: args.resource_detail_content_digest,
            content_size_bytes: args.resource_detail_content_size_bytes,
            media_type: args.resource_detail_media_type,
            format_metadata_json: args.resource_detail_format_metadata_json,
            detail_error_message: "resource observation detail requires exactly one of --resource-detail-content, --resource-detail-content-file, or --resource-detail-content-digest with --resource-detail-content-size-bytes",
        },
    )? {
        observation = observation.with_detail_content(detail_content);
    }
    if let Some(source_session_id) = source_session_id {
        observation = observation.with_source_session_id(source_session_id);
    }

    let scope = verify_resource_scope_from_cli(
        args.scope_payload_json,
        args.scope_path,
        args.scope_path_prefix,
        args.scope_glob,
        args.scope_git_worktree,
    )?
    .ok_or_else(|| {
        WorkVcsError::TaskInvalid(
            "verify resource observation requires one of --scope-payload-json, --scope-path, --scope-path-prefix, --scope-glob, or --scope-git-worktree"
                .to_owned(),
        )
    })?;
    let default_scope_kind = scope.default_scope_kind();
    let scope_kind = match args.scope_kind {
        Some(scope_kind) => scope_kind,
        None if let Some(scope_kind) = default_scope_kind => scope_kind.to_owned(),
        None => {
            return Err(WorkVcsError::TaskInvalid(
                "--scope-kind is required".to_owned(),
            ));
        }
    };
    let scope_schema_version = match args.scope_schema_version {
        Some(scope_schema_version) => scope_schema_version,
        None if default_scope_kind.is_some() => 1,
        None => {
            return Err(WorkVcsError::TaskInvalid(
                "--scope-schema-version is required".to_owned(),
            ));
        }
    };
    let scope_payload = scope.into_value();
    if uses_git_worktree_scope || uses_git_worktree_content {
        validate_git_worktree_verify_contract(
            &adapter_kind,
            adapter_schema_version,
            &scope_kind,
            scope_schema_version,
            &scope_payload,
        )?;
    }

    Ok(Some(VerifyResourceObservationInput::new(
        observation,
        scope_kind,
        scope_schema_version,
        scope_payload,
    )?))
}

fn applicability_stamp_from_cli(
    resource_basis_ordinal: i64,
    adapter_kind: String,
    adapter_schema_version: i64,
    scope_schema_version: i64,
    observation_status: &str,
    observed_fingerprint: Option<String>,
    observation: Option<String>,
) -> Result<ApplicabilityResourceStampInput> {
    let mut stamp = match parse_observation_status(observation_status)? {
        ApplicabilityResourceObservationStatus::Observed => {
            ApplicabilityResourceStampInput::observed(
                resource_basis_ordinal,
                adapter_kind,
                adapter_schema_version,
                scope_schema_version,
                Digest::from_hex(&required_arg(
                    "--observed-fingerprint",
                    observed_fingerprint,
                )?)?,
            )?
        }
        ApplicabilityResourceObservationStatus::Unavailable => {
            if observed_fingerprint.is_some() || observation.is_some() {
                return Err(WorkVcsError::TaskInvalid(
                    "unavailable resource stamp must not include observed data".to_owned(),
                ));
            }
            ApplicabilityResourceStampInput::unavailable(
                resource_basis_ordinal,
                adapter_kind,
                adapter_schema_version,
                scope_schema_version,
            )?
        }
        ApplicabilityResourceObservationStatus::Error => {
            if observed_fingerprint.is_some() || observation.is_some() {
                return Err(WorkVcsError::TaskInvalid(
                    "error resource stamp must not include observed data".to_owned(),
                ));
            }
            ApplicabilityResourceStampInput::error(
                resource_basis_ordinal,
                adapter_kind,
                adapter_schema_version,
                scope_schema_version,
            )?
        }
    };
    if let Some(observation) = observation {
        stamp = stamp.with_observation_id(ResourceObservationId::parse_canonical(&observation)?)?;
    }
    Ok(stamp)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LocalFileScopeMode {
    Path,
    PathPrefix,
    Glob,
}

impl LocalFileScopeMode {
    fn flag_name(self) -> &'static str {
        match self {
            Self::Path => "--resource-content-from-scope-path",
            Self::PathPrefix => "--resource-content-from-scope-path-prefix",
            Self::Glob => "--resource-content-from-scope-glob",
        }
    }

    fn payload_field(self) -> &'static str {
        match self {
            Self::Path => "path",
            Self::PathPrefix => "path_prefix",
            Self::Glob => "glob",
        }
    }

    fn description(self) -> &'static str {
        match self {
            Self::Path => "scope-path",
            Self::PathPrefix => "scope-path-prefix",
            Self::Glob => "scope-glob",
        }
    }
}

