enum ResourceBasisRefreshInput {
    LocalFile(LocalFileScopeInput),
    GitWorktree(GitWorktreeScope),
}

struct VerificationApplicabilityBatchRefreshResult {
    branch_id: BranchId,
    evaluated_commit_id: CommitId,
    caches: Vec<VerificationApplicabilityCacheSnapshot>,
}

fn refresh_resource_backed_verifications_from_basis(
    engine: &mut Engine,
    branch_id: BranchId,
    expected_evaluated_commit_id: Option<CommitId>,
    detail: CanonicalValue,
) -> Result<VerificationApplicabilityBatchRefreshResult> {
    let head = engine.branch_head(branch_id)?;
    if let Some(expected_evaluated_commit_id) = expected_evaluated_commit_id
        && head.head_commit_id != expected_evaluated_commit_id
    {
        return Err(WorkVcsError::BranchHeadConflict(format!(
            "branch {} expected head {}, found {}",
            branch_id, expected_evaluated_commit_id, head.head_commit_id
        )));
    }

    let verifications = engine
        .verifications_at(head.head_commit_id)?
        .into_iter()
        .filter(|verification| !verification.state.resource_basis.is_empty())
        .collect::<Vec<_>>();
    let refresh_inputs = verifications
        .iter()
        .map(|verification| {
            verification
                .state
                .resource_basis
                .iter()
                .map(resource_basis_refresh_input_from_basis)
                .collect::<Result<Vec<_>>>()
        })
        .collect::<Result<Vec<_>>>()?;

    let mut caches = Vec::with_capacity(verifications.len());
    for (verification, inputs) in verifications.iter().zip(refresh_inputs.iter()) {
        let mut resource_stamps = Vec::with_capacity(verification.state.resource_basis.len());
        for (index, (basis, input)) in verification
            .state
            .resource_basis
            .iter()
            .zip(inputs.iter())
            .enumerate()
        {
            let stamp = match input {
                ResourceBasisRefreshInput::LocalFile(input) => {
                    local_file_scope_applicability_stamp(engine, index, basis, input)?
                }
                ResourceBasisRefreshInput::GitWorktree(scope) => {
                    git_worktree_applicability_stamp(engine, index, basis, scope)?
                }
            };
            resource_stamps.push(stamp);
        }

        caches.push(
            engine.record_verification_applicability(
                VerificationApplicabilityRecordOptions::new(
                    branch_id,
                    verification.verification_entity_id,
                    head.head_commit_id,
                )?
                .with_resource_stamps(resource_stamps)?
                .with_detail(detail.clone())?,
            )?,
        );
    }

    Ok(VerificationApplicabilityBatchRefreshResult {
        branch_id,
        evaluated_commit_id: head.head_commit_id,
        caches,
    })
}

fn refresh_verification_applicability_from_resource_basis(
    engine: &mut Engine,
    branch_id: BranchId,
    verification_entity_id: EntityId,
    expected_evaluated_commit_id: Option<CommitId>,
    detail: CanonicalValue,
) -> Result<VerificationApplicabilityCacheSnapshot> {
    let head = engine.branch_head(branch_id)?;
    if let Some(expected_evaluated_commit_id) = expected_evaluated_commit_id
        && head.head_commit_id != expected_evaluated_commit_id
    {
        return Err(WorkVcsError::BranchHeadConflict(format!(
            "branch {} expected head {}, found {}",
            branch_id, expected_evaluated_commit_id, head.head_commit_id
        )));
    }
    let verification = engine.verification_at(head.head_commit_id, verification_entity_id)?;
    let resource_basis = verification.state.resource_basis.clone();
    if resource_basis.is_empty() {
        return Err(WorkVcsError::TaskInvalid(
            "--resource-content-from-basis requires verification resource basis".to_owned(),
        ));
    }

    let refresh_inputs = resource_basis
        .iter()
        .map(resource_basis_refresh_input_from_basis)
        .collect::<Result<Vec<_>>>()?;
    let mut resource_stamps = Vec::with_capacity(resource_basis.len());
    for (index, (basis, input)) in resource_basis.iter().zip(refresh_inputs.iter()).enumerate() {
        let stamp = match input {
            ResourceBasisRefreshInput::LocalFile(input) => {
                local_file_scope_applicability_stamp(engine, index, basis, input)?
            }
            ResourceBasisRefreshInput::GitWorktree(scope) => {
                git_worktree_applicability_stamp(engine, index, basis, scope)?
            }
        };
        resource_stamps.push(stamp);
    }

    engine.record_verification_applicability(
        VerificationApplicabilityRecordOptions::new(
            branch_id,
            verification_entity_id,
            head.head_commit_id,
        )?
        .with_resource_stamps(resource_stamps)?
        .with_detail(detail)?,
    )
}

fn resource_basis_refresh_input_from_basis(
    basis: &VerificationResourceBasis,
) -> Result<ResourceBasisRefreshInput> {
    match basis.adapter_kind.as_str() {
        "local-file" => {
            local_file_scope_from_basis_auto(basis).map(ResourceBasisRefreshInput::LocalFile)
        }
        "git" => git_worktree_scope_from_basis(basis).map(ResourceBasisRefreshInput::GitWorktree),
        adapter_kind => Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-basis does not support adapter_kind {adapter_kind:?}"
        ))),
    }
}

fn refresh_verification_applicability_from_local_file_scope(
    engine: &mut Engine,
    branch_id: BranchId,
    verification_entity_id: EntityId,
    expected_evaluated_commit_id: Option<CommitId>,
    detail: CanonicalValue,
    mode: LocalFileScopeMode,
) -> Result<VerificationApplicabilityCacheSnapshot> {
    let head = engine.branch_head(branch_id)?;
    if let Some(expected_evaluated_commit_id) = expected_evaluated_commit_id
        && head.head_commit_id != expected_evaluated_commit_id
    {
        return Err(WorkVcsError::BranchHeadConflict(format!(
            "branch {} expected head {}, found {}",
            branch_id, expected_evaluated_commit_id, head.head_commit_id
        )));
    }
    let verification = engine.verification_at(head.head_commit_id, verification_entity_id)?;
    let resource_basis = verification.state.resource_basis.clone();
    if resource_basis.is_empty() {
        return Err(WorkVcsError::TaskInvalid(format!(
            "{} requires verification resource basis",
            mode.flag_name()
        )));
    }

    let scoped_inputs = resource_basis
        .iter()
        .map(|basis| local_file_scope_from_basis(mode, basis))
        .collect::<Result<Vec<_>>>()?;
    let mut resource_stamps = Vec::with_capacity(resource_basis.len());
    for (index, (basis, input)) in resource_basis.iter().zip(scoped_inputs.iter()).enumerate() {
        resource_stamps.push(local_file_scope_applicability_stamp(
            engine, index, basis, input,
        )?);
    }

    engine.record_verification_applicability(
        VerificationApplicabilityRecordOptions::new(
            branch_id,
            verification_entity_id,
            head.head_commit_id,
        )?
        .with_resource_stamps(resource_stamps)?
        .with_detail(detail)?,
    )
}

fn refresh_verification_applicability_from_git_worktree_scope(
    engine: &mut Engine,
    branch_id: BranchId,
    verification_entity_id: EntityId,
    expected_evaluated_commit_id: Option<CommitId>,
    detail: CanonicalValue,
) -> Result<VerificationApplicabilityCacheSnapshot> {
    let head = engine.branch_head(branch_id)?;
    if let Some(expected_evaluated_commit_id) = expected_evaluated_commit_id
        && head.head_commit_id != expected_evaluated_commit_id
    {
        return Err(WorkVcsError::BranchHeadConflict(format!(
            "branch {} expected head {}, found {}",
            branch_id, expected_evaluated_commit_id, head.head_commit_id
        )));
    }
    let verification = engine.verification_at(head.head_commit_id, verification_entity_id)?;
    let resource_basis = verification.state.resource_basis.clone();
    if resource_basis.is_empty() {
        return Err(WorkVcsError::TaskInvalid(
            "--resource-content-from-scope-git-worktree requires verification resource basis"
                .to_owned(),
        ));
    }

    let scopes = resource_basis
        .iter()
        .map(git_worktree_scope_from_basis)
        .collect::<Result<Vec<_>>>()?;
    let mut resource_stamps = Vec::with_capacity(resource_basis.len());
    for (index, (basis, scope)) in resource_basis.iter().zip(scopes.iter()).enumerate() {
        resource_stamps.push(git_worktree_applicability_stamp(
            engine, index, basis, scope,
        )?);
    }

    engine.record_verification_applicability(
        VerificationApplicabilityRecordOptions::new(
            branch_id,
            verification_entity_id,
            head.head_commit_id,
        )?
        .with_resource_stamps(resource_stamps)?
        .with_detail(detail)?,
    )
}

fn git_worktree_applicability_stamp(
    engine: &mut Engine,
    resource_basis_ordinal: usize,
    basis: &VerificationResourceBasis,
    scope: &GitWorktreeScope,
) -> Result<ApplicabilityResourceStampInput> {
    match git_worktree_snapshot(&scope.repo) {
        Ok(snapshot) => {
            let observation =
                engine.record_resource_observation(ResourceObservationCreateOptions::new(
                    basis.resource_id,
                    basis.adapter_kind.clone(),
                    basis.adapter_schema_version,
                    snapshot.fingerprint,
                    snapshot.summary,
                )?)?;
            ApplicabilityResourceStampInput::observed(
                resource_basis_ordinal as i64,
                basis.adapter_kind.clone(),
                basis.adapter_schema_version,
                basis.scope_schema_version,
                snapshot.fingerprint,
            )?
            .with_observation_id(observation.observation_id)
        }
        Err(GitWorktreeReadFailure::Unavailable) => ApplicabilityResourceStampInput::unavailable(
            resource_basis_ordinal as i64,
            basis.adapter_kind.clone(),
            basis.adapter_schema_version,
            basis.scope_schema_version,
        ),
        Err(GitWorktreeReadFailure::Error(_)) => ApplicabilityResourceStampInput::error(
            resource_basis_ordinal as i64,
            basis.adapter_kind.clone(),
            basis.adapter_schema_version,
            basis.scope_schema_version,
        ),
    }
}

fn validate_git_worktree_verify_contract(
    adapter_kind: &str,
    adapter_schema_version: i64,
    scope_kind: &str,
    scope_schema_version: i64,
    scope_payload: &CanonicalValue,
) -> Result<()> {
    if adapter_kind != "git" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--scope-git-worktree supports adapter_kind git, found {adapter_kind:?}"
        )));
    }
    if adapter_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--scope-git-worktree supports adapter_schema_version 1, found {adapter_schema_version}"
        )));
    }
    if scope_kind != "git-worktree" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--scope-git-worktree supports scope_kind git-worktree, found {scope_kind:?}"
        )));
    }
    if scope_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--scope-git-worktree supports scope_schema_version 1, found {scope_schema_version}"
        )));
    }
    git_worktree_scope_from_payload(scope_payload)?;
    Ok(())
}

fn git_worktree_scope_from_basis(basis: &VerificationResourceBasis) -> Result<GitWorktreeScope> {
    if basis.adapter_kind != "git" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-scope-git-worktree supports adapter_kind git, found {:?}",
            basis.adapter_kind
        )));
    }
    if basis.adapter_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-scope-git-worktree supports adapter_schema_version 1, found {}",
            basis.adapter_schema_version
        )));
    }
    if basis.scope_kind != "git-worktree" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-scope-git-worktree supports scope_kind git-worktree, found {:?}",
            basis.scope_kind
        )));
    }
    if basis.scope_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-scope-git-worktree supports scope_schema_version 1, found {}",
            basis.scope_schema_version
        )));
    }
    git_worktree_scope_from_payload(&basis.scope_payload)
}

fn git_worktree_scope_from_payload(scope_payload: &CanonicalValue) -> Result<GitWorktreeScope> {
    let CanonicalValue::Object(entries) = scope_payload else {
        return Err(WorkVcsError::TaskInvalid(
            "git worktree refresh requires object scope payload".to_owned(),
        ));
    };
    if entries.len() != 1 {
        return Err(WorkVcsError::TaskInvalid(
            "git worktree refresh requires scope payload with only field repo".to_owned(),
        ));
    }
    let (key, repo) = &entries[0];
    if key != "repo" {
        return Err(WorkVcsError::TaskInvalid(
            "git worktree refresh requires scope payload field repo".to_owned(),
        ));
    };
    let CanonicalValue::String(repo) = repo else {
        return Err(WorkVcsError::TaskInvalid(
            "git worktree refresh requires string scope payload field repo".to_owned(),
        ));
    };
    Ok(GitWorktreeScope {
        repo: PathBuf::from(repo),
    })
}

fn local_file_scope_applicability_stamp(
    engine: &mut Engine,
    resource_basis_ordinal: usize,
    basis: &VerificationResourceBasis,
    input: &LocalFileScopeInput,
) -> Result<ApplicabilityResourceStampInput> {
    match observe_local_file_scope(input)? {
        LocalFileScopeObservation::Observed(observed) => {
            let observation =
                engine.record_resource_observation(ResourceObservationCreateOptions::new(
                    basis.resource_id,
                    basis.adapter_kind.clone(),
                    basis.adapter_schema_version,
                    observed.fingerprint,
                    observed.summary,
                )?)?;
            ApplicabilityResourceStampInput::observed(
                resource_basis_ordinal as i64,
                basis.adapter_kind.clone(),
                basis.adapter_schema_version,
                basis.scope_schema_version,
                observed.fingerprint,
            )?
            .with_observation_id(observation.observation_id)
        }
        LocalFileScopeObservation::Unavailable => ApplicabilityResourceStampInput::unavailable(
            resource_basis_ordinal as i64,
            basis.adapter_kind.clone(),
            basis.adapter_schema_version,
            basis.scope_schema_version,
        ),
        LocalFileScopeObservation::Error => ApplicabilityResourceStampInput::error(
            resource_basis_ordinal as i64,
            basis.adapter_kind.clone(),
            basis.adapter_schema_version,
            basis.scope_schema_version,
        ),
    }
}

fn local_file_scope_from_basis_auto(
    basis: &VerificationResourceBasis,
) -> Result<LocalFileScopeInput> {
    if basis.adapter_kind != "local-file" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-basis supports adapter_kind local-file, found {:?}",
            basis.adapter_kind
        )));
    }
    if basis.adapter_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-basis supports local-file adapter_schema_version 1, found {}",
            basis.adapter_schema_version
        )));
    }
    if basis.scope_kind != "path" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-basis supports local-file scope_kind path, found {:?}",
            basis.scope_kind
        )));
    }
    if basis.scope_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "--resource-content-from-basis supports local-file scope_schema_version 1, found {}",
            basis.scope_schema_version
        )));
    }

    let CanonicalValue::Object(entries) = &basis.scope_payload else {
        return Err(WorkVcsError::TaskInvalid(
            "local-file basis refresh requires object scope payload".to_owned(),
        ));
    };
    if entries.len() != 1 {
        return Err(WorkVcsError::TaskInvalid(
            "local-file basis refresh requires scope payload with exactly one of path, path_prefix, or glob".to_owned(),
        ));
    }
    let (key, path) = &entries[0];
    let CanonicalValue::String(path) = path else {
        return Err(WorkVcsError::TaskInvalid(format!(
            "local-file basis refresh requires string scope payload field {key}"
        )));
    };
    match key.as_str() {
        "path" => Ok(LocalFileScopeInput::Path(PathBuf::from(path))),
        "path_prefix" => Ok(LocalFileScopeInput::PathPrefix(PathBuf::from(path))),
        "glob" => Ok(LocalFileScopeInput::Glob(
            local_file_glob_scope_from_pattern(path)?,
        )),
        _ => Err(WorkVcsError::TaskInvalid(format!(
            "local-file basis refresh does not support scope payload field {key:?}"
        ))),
    }
}

fn local_file_scope_from_basis(
    mode: LocalFileScopeMode,
    basis: &VerificationResourceBasis,
) -> Result<LocalFileScopeInput> {
    if basis.adapter_kind != "local-file" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "{} supports adapter_kind local-file, found {:?}",
            mode.flag_name(),
            basis.adapter_kind
        )));
    }
    if basis.scope_kind != "path" {
        return Err(WorkVcsError::TaskInvalid(format!(
            "{} supports scope_kind path, found {:?}",
            mode.flag_name(),
            basis.scope_kind
        )));
    }
    if basis.scope_schema_version != 1 {
        return Err(WorkVcsError::TaskInvalid(format!(
            "{} supports scope_schema_version 1, found {}",
            mode.flag_name(),
            basis.scope_schema_version
        )));
    }

    let CanonicalValue::Object(entries) = &basis.scope_payload else {
        return Err(WorkVcsError::TaskInvalid(format!(
            "local-file {} refresh requires object scope payload",
            mode.description()
        )));
    };
    let payload_field = mode.payload_field();
    let Some((_, path)) = entries.iter().find(|(key, _)| key == payload_field) else {
        return Err(WorkVcsError::TaskInvalid(format!(
            "local-file {} refresh requires scope payload field {}",
            mode.description(),
            payload_field
        )));
    };
    let CanonicalValue::String(path) = path else {
        return Err(WorkVcsError::TaskInvalid(format!(
            "local-file {} refresh requires string scope payload field {}",
            mode.description(),
            payload_field
        )));
    };
    Ok(match mode {
        LocalFileScopeMode::Path => LocalFileScopeInput::Path(PathBuf::from(path)),
        LocalFileScopeMode::PathPrefix => LocalFileScopeInput::PathPrefix(PathBuf::from(path)),
        LocalFileScopeMode::Glob => {
            LocalFileScopeInput::Glob(local_file_glob_scope_from_pattern(path)?)
        }
    })
}

fn observe_local_file_scope(input: &LocalFileScopeInput) -> Result<LocalFileScopeObservation> {
    match input {
        LocalFileScopeInput::Path(path) => match fs::read(path) {
            Ok(bytes) => Ok(LocalFileScopeObservation::Observed(
                LocalFileScopeObserved {
                    fingerprint: content_object_digest(&bytes),
                    summary: local_file_scope_path_observation_summary(path)?,
                },
            )),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                Ok(LocalFileScopeObservation::Unavailable)
            }
            Err(_) => Ok(LocalFileScopeObservation::Error),
        },
        LocalFileScopeInput::PathPrefix(path_prefix) => {
            match local_file_path_prefix_snapshot(path_prefix) {
                Ok(snapshot) => Ok(LocalFileScopeObservation::Observed(
                    LocalFileScopeObserved {
                        fingerprint: snapshot.fingerprint,
                        summary: snapshot.summary,
                    },
                )),
                Err(LocalFilePathPrefixReadFailure::Unavailable) => {
                    Ok(LocalFileScopeObservation::Unavailable)
                }
                Err(LocalFilePathPrefixReadFailure::Error(_)) => {
                    Ok(LocalFileScopeObservation::Error)
                }
            }
        }
        LocalFileScopeInput::Glob(scope) => match local_file_glob_snapshot(&scope.pattern) {
            Ok(snapshot) => Ok(LocalFileScopeObservation::Observed(
                LocalFileScopeObserved {
                    fingerprint: snapshot.fingerprint,
                    summary: snapshot.summary,
                },
            )),
            Err(LocalFileGlobReadFailure::Unavailable) => {
                Ok(LocalFileScopeObservation::Unavailable)
            }
            Err(LocalFileGlobReadFailure::Error(_)) => Ok(LocalFileScopeObservation::Error),
        },
    }
}

fn local_file_path_prefix_snapshot(
    path_prefix: &Path,
) -> std::result::Result<LocalFilePathPrefixSnapshot, LocalFilePathPrefixReadFailure> {
    let root_metadata = fs::symlink_metadata(path_prefix).map_err(|error| {
        if error.kind() == std::io::ErrorKind::NotFound {
            LocalFilePathPrefixReadFailure::Unavailable
        } else {
            LocalFilePathPrefixReadFailure::Error(format!(
                "failed to inspect path prefix {}: {error}",
                path_prefix.display()
            ))
        }
    })?;
    if !root_metadata.is_dir() {
        return Err(LocalFilePathPrefixReadFailure::Error(format!(
            "path prefix {} is not a directory",
            path_prefix.display()
        )));
    }

    let mut directories = vec![path_prefix.to_path_buf()];
    let mut files = Vec::new();
    while let Some(directory) = directories.pop() {
        let entries = fs::read_dir(&directory).map_err(|error| {
            LocalFilePathPrefixReadFailure::Error(format!(
                "failed to read directory {}: {error}",
                directory.display()
            ))
        })?;
        for entry in entries {
            let entry = entry.map_err(|error| {
                LocalFilePathPrefixReadFailure::Error(format!(
                    "failed to read directory entry {}: {error}",
                    directory.display()
                ))
            })?;
            let entry_path = entry.path();
            let file_type = entry.file_type().map_err(|error| {
                LocalFilePathPrefixReadFailure::Error(format!(
                    "failed to inspect path-prefix entry {}: {error}",
                    entry_path.display()
                ))
            })?;
            if file_type.is_dir() {
                directories.push(entry_path);
            } else if file_type.is_file() {
                let relative_path = local_file_path_prefix_relative_path(path_prefix, &entry_path)?;
                let bytes = fs::read(&entry_path).map_err(|error| {
                    LocalFilePathPrefixReadFailure::Error(format!(
                        "failed to read path-prefix file {}: {error}",
                        entry_path.display()
                    ))
                })?;
                let size_bytes = i64::try_from(bytes.len()).map_err(|_| {
                    LocalFilePathPrefixReadFailure::Error(format!(
                        "path-prefix file {} is too large",
                        entry_path.display()
                    ))
                })?;
                files.push(LocalFilePathPrefixEntry {
                    path: relative_path,
                    fingerprint: content_object_digest(&bytes),
                    size_bytes,
                });
            } else {
                return Err(LocalFilePathPrefixReadFailure::Error(format!(
                    "unsupported path-prefix entry {}",
                    entry_path.display()
                )));
            }
        }
    }
    files.sort_by(|left, right| left.path.cmp(&right.path));

    let mut total_size_bytes = 0_i64;
    for file in &files {
        total_size_bytes = total_size_bytes
            .checked_add(file.size_bytes)
            .ok_or_else(|| {
                LocalFilePathPrefixReadFailure::Error(format!(
                    "path prefix {} total size is too large",
                    path_prefix.display()
                ))
            })?;
    }
    let fingerprint = local_file_path_prefix_fingerprint(&files)?;
    Ok(LocalFilePathPrefixSnapshot {
        fingerprint,
        summary: local_file_scope_path_prefix_observation_summary(
            path_prefix,
            files.len(),
            total_size_bytes,
        )
        .map_err(|error| LocalFilePathPrefixReadFailure::Error(error.to_string()))?,
    })
}

fn local_file_path_prefix_relative_path(
    path_prefix: &Path,
    path: &Path,
) -> std::result::Result<String, LocalFilePathPrefixReadFailure> {
    let relative = path.strip_prefix(path_prefix).map_err(|error| {
        LocalFilePathPrefixReadFailure::Error(format!(
            "failed to derive relative path for {} under {}: {error}",
            path.display(),
            path_prefix.display()
        ))
    })?;
    normalize_cli_scope_path_components(relative).map_err(|error| {
        LocalFilePathPrefixReadFailure::Error(format!(
            "failed to normalize relative path for {}: {error}",
            path.display()
        ))
    })
}

fn local_file_path_prefix_fingerprint(
    files: &[LocalFilePathPrefixEntry],
) -> std::result::Result<Digest, LocalFilePathPrefixReadFailure> {
    let entries = files
        .iter()
        .map(|file| {
            CanonicalValue::object(vec![
                ("path".to_owned(), CanonicalValue::String(file.path.clone())),
                (
                    "fingerprint".to_owned(),
                    CanonicalValue::String(file.fingerprint.to_string()),
                ),
                (
                    "size_bytes".to_owned(),
                    CanonicalValue::safe_integer(file.size_bytes).map_err(|error| {
                        LocalFilePathPrefixReadFailure::Error(error.to_string())
                    })?,
                ),
            ])
            .map_err(|error| LocalFilePathPrefixReadFailure::Error(error.to_string()))
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let manifest = CanonicalValue::object(vec![
        (
            "manifest_profile".to_owned(),
            CanonicalValue::String("local-file-path-prefix-manifest-v1".to_owned()),
        ),
        ("files".to_owned(), CanonicalValue::Array(entries)),
    ])
    .map_err(|error| LocalFilePathPrefixReadFailure::Error(error.to_string()))?;
    let manifest_bytes = canonical_bytes(&manifest)
        .map_err(|error| LocalFilePathPrefixReadFailure::Error(error.to_string()))?;
    Ok(content_object_digest(&manifest_bytes))
}

fn local_file_glob_scope_from_pattern(pattern: &str) -> Result<LocalFileGlobScope> {
    let normalized_pattern = normalize_cli_scope_glob(pattern)?;
    Pattern::new(&normalized_pattern).map_err(|error| {
        WorkVcsError::TaskInvalid(format!("scope glob pattern is invalid: {error}"))
    })?;
    if !local_file_glob_has_wildcard(&normalized_pattern) {
        return Err(WorkVcsError::TaskInvalid(
            "scope glob requires at least one wildcard; use --scope-path for exact files"
                .to_owned(),
        ));
    }
    let root = local_file_glob_fixed_root(&normalized_pattern)?;
    Ok(LocalFileGlobScope {
        pattern: normalized_pattern,
        root,
    })
}

fn local_file_glob_has_wildcard(pattern: &str) -> bool {
    pattern
        .bytes()
        .any(|byte| matches!(byte, b'*' | b'?' | b'['))
}

fn local_file_glob_segment_has_wildcard(segment: &str) -> bool {
    segment
        .bytes()
        .any(|byte| matches!(byte, b'*' | b'?' | b'['))
}

fn local_file_glob_fixed_root(pattern: &str) -> Result<PathBuf> {
    let mut root = PathBuf::new();
    let mut fixed_normal_segments = 0_usize;
    for component in Path::new(pattern).components() {
        match component {
            Component::Prefix(path_prefix) => root.push(path_prefix.as_os_str()),
            Component::RootDir => root.push(component.as_os_str()),
            Component::CurDir => {}
            Component::ParentDir => {
                return Err(WorkVcsError::TaskInvalid(
                    "scope glob fixed root must not contain parent directory segments".to_owned(),
                ));
            }
            Component::Normal(segment) => {
                let text = segment.to_str().ok_or_else(|| {
                    WorkVcsError::TaskInvalid("scope glob must be valid UTF-8".to_owned())
                })?;
                if local_file_glob_segment_has_wildcard(text) {
                    break;
                }
                root.push(segment);
                fixed_normal_segments += 1;
            }
        }
    }
    if fixed_normal_segments == 0 {
        return Err(WorkVcsError::TaskInvalid(
            "scope glob requires a fixed non-wildcard root before the first wildcard segment"
                .to_owned(),
        ));
    }
    Ok(root)
}

fn local_file_glob_match_options() -> MatchOptions {
    MatchOptions {
        case_sensitive: true,
        require_literal_separator: true,
        require_literal_leading_dot: true,
    }
}

fn local_file_glob_snapshot(
    pattern: &str,
) -> std::result::Result<LocalFileGlobSnapshot, LocalFileGlobReadFailure> {
    let scope = local_file_glob_scope_from_pattern(pattern)
        .map_err(|error| LocalFileGlobReadFailure::Error(error.to_string()))?;
    let root_metadata = fs::symlink_metadata(&scope.root).map_err(|error| {
        if error.kind() == std::io::ErrorKind::NotFound {
            LocalFileGlobReadFailure::Unavailable
        } else {
            LocalFileGlobReadFailure::Error(format!(
                "failed to inspect glob root {}: {error}",
                scope.root.display()
            ))
        }
    })?;
    if !root_metadata.is_dir() {
        return Err(LocalFileGlobReadFailure::Error(format!(
            "glob root {} is not a directory",
            scope.root.display()
        )));
    }

    let mut files = Vec::new();
    let paths = glob_with(&scope.pattern, local_file_glob_match_options()).map_err(|error| {
        LocalFileGlobReadFailure::Error(format!(
            "failed to compile glob pattern {:?}: {error}",
            scope.pattern
        ))
    })?;
    for entry in paths {
        let entry_path = entry.map_err(|error| {
            LocalFileGlobReadFailure::Error(format!(
                "failed to read glob match for {:?}: {error}",
                scope.pattern
            ))
        })?;
        let metadata = fs::symlink_metadata(&entry_path).map_err(|error| {
            LocalFileGlobReadFailure::Error(format!(
                "failed to inspect glob match {}: {error}",
                entry_path.display()
            ))
        })?;
        if !metadata.is_file() {
            return Err(LocalFileGlobReadFailure::Error(format!(
                "unsupported glob match {}",
                entry_path.display()
            )));
        }
        let relative_path = local_file_glob_relative_path(&scope, &entry_path)?;
        let bytes = fs::read(&entry_path).map_err(|error| {
            LocalFileGlobReadFailure::Error(format!(
                "failed to read glob file {}: {error}",
                entry_path.display()
            ))
        })?;
        let size_bytes = i64::try_from(bytes.len()).map_err(|_| {
            LocalFileGlobReadFailure::Error(format!(
                "glob file {} is too large",
                entry_path.display()
            ))
        })?;
        files.push(LocalFileGlobEntry {
            path: relative_path,
            fingerprint: content_object_digest(&bytes),
            size_bytes,
        });
    }
    files.sort_by(|left, right| left.path.cmp(&right.path));

    let mut total_size_bytes = 0_i64;
    for file in &files {
        total_size_bytes = total_size_bytes
            .checked_add(file.size_bytes)
            .ok_or_else(|| {
                LocalFileGlobReadFailure::Error(format!(
                    "glob pattern {:?} total size is too large",
                    scope.pattern
                ))
            })?;
    }
    let fingerprint = local_file_glob_fingerprint(&files)?;
    Ok(LocalFileGlobSnapshot {
        fingerprint,
        summary: local_file_scope_glob_observation_summary(&scope, files.len(), total_size_bytes)
            .map_err(|error| LocalFileGlobReadFailure::Error(error.to_string()))?,
    })
}

fn local_file_glob_relative_path(
    scope: &LocalFileGlobScope,
    path: &Path,
) -> std::result::Result<String, LocalFileGlobReadFailure> {
    let relative = if scope.root == Path::new(".") {
        path
    } else {
        path.strip_prefix(&scope.root).map_err(|error| {
            LocalFileGlobReadFailure::Error(format!(
                "failed to derive relative path for {} under {}: {error}",
                path.display(),
                scope.root.display()
            ))
        })?
    };
    normalize_cli_scope_path_components(relative).map_err(|error| {
        LocalFileGlobReadFailure::Error(format!(
            "failed to normalize relative path for {}: {error}",
            path.display()
        ))
    })
}

fn local_file_glob_fingerprint(
    files: &[LocalFileGlobEntry],
) -> std::result::Result<Digest, LocalFileGlobReadFailure> {
    let entries = files
        .iter()
        .map(|file| {
            CanonicalValue::object(vec![
                ("path".to_owned(), CanonicalValue::String(file.path.clone())),
                (
                    "fingerprint".to_owned(),
                    CanonicalValue::String(file.fingerprint.to_string()),
                ),
                (
                    "size_bytes".to_owned(),
                    CanonicalValue::safe_integer(file.size_bytes)
                        .map_err(|error| LocalFileGlobReadFailure::Error(error.to_string()))?,
                ),
            ])
            .map_err(|error| LocalFileGlobReadFailure::Error(error.to_string()))
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let manifest = CanonicalValue::object(vec![
        (
            "manifest_profile".to_owned(),
            CanonicalValue::String("local-file-glob-manifest-v1".to_owned()),
        ),
        ("files".to_owned(), CanonicalValue::Array(entries)),
    ])
    .map_err(|error| LocalFileGlobReadFailure::Error(error.to_string()))?;
    let manifest_bytes = canonical_bytes(&manifest)
        .map_err(|error| LocalFileGlobReadFailure::Error(error.to_string()))?;
    Ok(content_object_digest(&manifest_bytes))
}

