    #[test]
    fn cli_rejects_verification_requirement_session_focus() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let genesis = value(&workspace, "genesis_commit_id");

        let task = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &genesis,
            "--description",
            "Unsupported focus task",
        ])
        .expect("parse task"))
        .expect("create task");
        let task_id = value(&task, "task_entity_id");

        let criterion = run(Cli::try_parse_from([
            "workvcs",
            "ac",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&task, "commit_id"),
            "--task",
            &task_id,
            "--task-version",
            &value(&task, "task_entity_version_id"),
            "--local-key",
            "AC-unsupported-focus",
            "--statement",
            "The unsupported focus requirement is visible.",
        ])
        .expect("parse ac create"))
        .expect("create ac");

        let requirement = run(Cli::try_parse_from([
            "workvcs",
            "vr",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&criterion, "commit_id"),
            "--criterion",
            &value(&criterion, "acceptance_criterion_entity_id"),
            "--criterion-version",
            &value(&criterion, "acceptance_criterion_entity_version_id"),
            "--local-key",
            "VR-unsupported-focus",
            "--statement",
            "Do not allow this requirement as session focus.",
        ])
        .expect("parse vr create"))
        .expect("create vr");
        let requirement_id = value(&requirement, "verification_requirement_entity_id");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let rejected = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "focus-set",
            store,
            "--session",
            &session_id,
            "--focus",
            &requirement_id,
        ])
        .expect("parse vr focus set"));
        assert!(matches!(
            rejected,
            Err(WorkVcsError::SessionInvalid(message))
                if message.contains("is not a current Goal, Plan, or Task at branch head")
        ));

        let unchanged = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "show",
            store,
            "--session",
            &session_id,
            "--expected-focus",
            "none",
        ])
        .expect("parse unchanged session show"))
        .expect("show unchanged session");
        assert_eq!(value(&unchanged, "focus_entity_id"), "none");
        assert_eq!(value(&unchanged, "focus_matches_expected"), "true");
    }

    #[test]
    fn cli_marks_session_potentially_stale_and_preserves_recovery_path() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let genesis = value(&workspace, "genesis_commit_id");

        let task = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &genesis,
            "--description",
            "Stale session task",
        ])
        .expect("parse task"))
        .expect("create task");
        let task_id = value(&task, "task_entity_id");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let marked = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "mark-stale",
            store,
            "--session",
            &session_id,
            "--rationale",
            "operator observed no heartbeat",
            "--expected-session",
            &session_id,
            "--expected-lifecycle-state",
            "potentially_stale",
            "--expected-active-workspace",
            &workspace_id,
            "--expected-active-branch",
            &branch,
        ])
        .expect("parse session mark-stale"))
        .expect("mark session stale");
        assert_eq!(value(&marked, "session_id"), session_id);
        assert_eq!(value(&marked, "lifecycle_state"), "potentially_stale");
        assert_eq!(
            value(&marked, "rationale"),
            "operator observed no heartbeat"
        );
        assert_eq!(value(&marked, "session_match_expected"), "true");
        assert_eq!(value(&marked, "lifecycle_state_match_expected"), "true");
        assert_eq!(value(&marked, "active_workspace_match_expected"), "true");
        assert_eq!(value(&marked, "active_branch_match_expected"), "true");

        let shown = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "show",
            store,
            "--session",
            &session_id,
            "--expected-lifecycle-state",
            "potentially_stale",
            "--expected-active-workspace",
            &workspace_id,
            "--expected-active-branch",
            &branch,
        ])
        .expect("parse stale session show"))
        .expect("show stale session");
        assert_eq!(value(&shown, "lifecycle_state"), "potentially_stale");
        assert_eq!(value(&shown, "lifecycle_state_matches_expected"), "true");
        assert_eq!(value(&shown, "active_workspace_matches_expected"), "true");
        assert_eq!(value(&shown, "active_branch_matches_expected"), "true");

        let listed = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "list",
            store,
            "--lifecycle",
            "potentially_stale",
            "--expected-sessions",
            "1",
        ])
        .expect("parse stale session list"))
        .expect("list stale sessions");
        assert_eq!(value(&listed, "sessions"), "1");
        assert_eq!(value(&listed, "session.0.session_id"), session_id);
        assert_eq!(
            value(&listed, "session.0.lifecycle_state"),
            "potentially_stale"
        );
        assert_eq!(value(&listed, "sessions_match_expected"), "true");

        let stale_claim = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "task",
            store,
            "--session",
            &session_id,
            "--task",
            &task_id,
        ])
        .expect("parse stale claim"));
        assert!(matches!(
            stale_claim,
            Err(WorkVcsError::SessionInvalid(message))
                if message == format!("session {session_id} is not active")
        ));

        let ended = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "end",
            store,
            "--session",
            &session_id,
            "--expected-lifecycle-state",
            "ended",
        ])
        .expect("parse stale session end"))
        .expect("end stale session");
        assert_eq!(value(&ended, "lifecycle_state"), "ended");
        assert_eq!(value(&ended, "lifecycle_state_match_expected"), "true");
    }

    #[test]
    fn cli_runs_focused_handoff_workflow() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let genesis = value(&workspace, "genesis_commit_id");

        let task = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &genesis,
            "--description",
            "Focused handoff task",
        ])
        .expect("parse task"))
        .expect("create task");
        let task_id = value(&task, "task_entity_id");
        let task_head = value(&task, "commit_id");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        run(Cli::try_parse_from([
            "workvcs",
            "session",
            "focus-set",
            store,
            "--session",
            &session_id,
            "--focus",
            &task_id,
            "--expected-focus",
            &task_id,
        ])
        .expect("parse session focus set"))
        .expect("set session focus");

        let ended = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "end",
            store,
            "--session",
            &session_id,
            "--summary-json",
            r#"{"z_result":"handoff","next":"resume task"}"#,
            "--expected-session",
            &session_id,
            "--expected-lifecycle-state",
            "ended",
        ])
        .expect("parse session end"))
        .expect("end session");
        let session_diff_id = value(&ended, "session_diff_id");
        assert_eq!(value(&ended, "session_match_expected"), "true");
        assert_eq!(value(&ended, "lifecycle_state_match_expected"), "true");

        let handoff = run(Cli::try_parse_from([
            "workvcs",
            "handoff",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &task_head,
            "--session",
            &session_id,
            "--statement",
            "Continue focused implementation from ended session",
            "--session-diff",
            &session_diff_id,
            "--focus",
            &task_id,
            "--expected-session-diff",
            &session_diff_id,
            "--expected-focus",
            &task_id,
        ])
        .expect("parse handoff create"))
        .expect("create focused handoff");
        let handoff_id = value(&handoff, "record_entity_id");
        let handoff_commit = value(&handoff, "commit_id");
        assert_eq!(value(&handoff, "record_kind"), "handoff");
        assert_eq!(value(&handoff, "handoff_scope_recognized"), "true");
        assert_eq!(value(&handoff, "session_id"), session_id);
        assert_eq!(value(&handoff, "session_lifecycle_state"), "ended");
        assert_eq!(value(&handoff, "session_diff_id"), session_diff_id);
        assert_eq!(value(&handoff, "focus_entity_id"), task_id);
        assert_eq!(value(&handoff, "session_diff_found"), "true");
        assert_eq!(
            value(&handoff, "session_diff_summary_json"),
            r#"{"next":"resume task","z_result":"handoff"}"#
        );
        assert_eq!(value(&handoff, "session_diff_matches_expected"), "true");
        assert_eq!(value(&handoff, "focus_matches_expected"), "true");

        let shown = run(Cli::try_parse_from([
            "workvcs",
            "handoff",
            "show",
            store,
            "--commit",
            &handoff_commit,
            "--handoff",
            &handoff_id,
            "--expected-session",
            &session_id,
            "--expected-session-diff",
            &session_diff_id,
            "--expected-focus",
            &task_id,
        ])
        .expect("parse handoff show"))
        .expect("show focused handoff");
        assert_eq!(value(&shown, "record_kind"), "handoff");
        assert_eq!(value(&shown, "handoff_scope_recognized"), "true");
        assert_eq!(value(&shown, "session_id"), session_id);
        assert_eq!(value(&shown, "session_lifecycle_state"), "ended");
        assert_eq!(value(&shown, "session_diff_id"), session_diff_id);
        assert_eq!(value(&shown, "focus_entity_id"), task_id);
        assert_eq!(value(&shown, "session_diff_found"), "true");
        assert_eq!(value(&shown, "session_matches_expected"), "true");
        assert_eq!(value(&shown, "session_diff_matches_expected"), "true");
        assert_eq!(value(&shown, "focus_matches_expected"), "true");

        let handoff_why = run(Cli::try_parse_from([
            "workvcs",
            "why",
            store,
            "--commit",
            &handoff_commit,
            "--entity",
            &handoff_id,
            "--expected-relation-edges",
            "0",
            "--expected-scope-links",
            "1",
        ])
        .expect("parse handoff why"))
        .expect("why focused handoff");
        assert_eq!(value(&handoff_why, "relation_edges"), "0");
        assert_eq!(value(&handoff_why, "relation_edges_match_expected"), "true");
        assert_eq!(value(&handoff_why, "scope_links"), "1");
        assert_eq!(value(&handoff_why, "scope_links_match_expected"), "true");
        assert_eq!(
            value(&handoff_why, "scope_link.0.link_kind"),
            "handoff_focus"
        );
        assert_eq!(value(&handoff_why, "scope_link.0.direction"), "outgoing");
        assert_eq!(value(&handoff_why, "scope_link.0.source_kind"), "entity");
        assert_eq!(
            value(&handoff_why, "scope_link.0.source_entity_kind"),
            "record"
        );
        assert_eq!(
            value(&handoff_why, "scope_link.0.source_entity_id"),
            handoff_id
        );
        assert_eq!(value(&handoff_why, "scope_link.0.target_kind"), "entity");
        assert_eq!(
            value(&handoff_why, "scope_link.0.target_entity_kind"),
            "task"
        );
        assert_eq!(
            value(&handoff_why, "scope_link.0.target_entity_id"),
            task_id
        );

        let focus_why = run(Cli::try_parse_from([
            "workvcs",
            "why",
            store,
            "--commit",
            &handoff_commit,
            "--entity",
            &task_id,
            "--expected-relation-edges",
            "0",
            "--expected-scope-links",
            "1",
        ])
        .expect("parse focus why"))
        .expect("why handoff focus task");
        assert_eq!(value(&focus_why, "relation_edges"), "0");
        assert_eq!(value(&focus_why, "relation_edges_match_expected"), "true");
        assert_eq!(value(&focus_why, "scope_links"), "1");
        assert_eq!(value(&focus_why, "scope_links_match_expected"), "true");
        assert_eq!(value(&focus_why, "scope_link.0.link_kind"), "handoff_focus");
        assert_eq!(value(&focus_why, "scope_link.0.direction"), "incoming");
        assert_eq!(value(&focus_why, "scope_link.0.source_kind"), "entity");
        assert_eq!(
            value(&focus_why, "scope_link.0.source_entity_kind"),
            "record"
        );
        assert_eq!(
            value(&focus_why, "scope_link.0.source_entity_id"),
            handoff_id
        );
        assert_eq!(value(&focus_why, "scope_link.0.target_kind"), "entity");
        assert_eq!(value(&focus_why, "scope_link.0.target_entity_kind"), "task");
        assert_eq!(value(&focus_why, "scope_link.0.target_entity_id"), task_id);

        let continuation = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse continuation session start"))
        .expect("start continuation session");
        let continuation_session_id = value(&continuation, "session_id");

        let mismatched_source_consume = run(Cli::try_parse_from([
            "workvcs",
            "handoff",
            "consume",
            store,
            "--commit",
            &handoff_commit,
            "--handoff",
            &handoff_id,
            "--session",
            &continuation_session_id,
            "--expected-source-session",
            &continuation_session_id,
        ])
        .expect("parse mismatched handoff consume"));
        assert!(mismatched_source_consume.is_err());

        let unchanged_after_mismatch = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "show",
            store,
            "--session",
            &continuation_session_id,
            "--expected-focus",
            "none",
        ])
        .expect("parse session show after mismatched consume"))
        .expect("show session after mismatched consume");
        assert_eq!(
            value(&unchanged_after_mismatch, "focus_matches_expected"),
            "true"
        );
        assert_eq!(value(&unchanged_after_mismatch, "focus_entity_id"), "none");

        let consumed = run(Cli::try_parse_from([
            "workvcs",
            "handoff",
            "consume",
            store,
            "--commit",
            &handoff_commit,
            "--handoff",
            &handoff_id,
            "--session",
            &continuation_session_id,
            "--expected-source-session",
            &session_id,
            "--expected-session-diff",
            &session_diff_id,
            "--expected-focus",
            &task_id,
            "--expected-session",
            &continuation_session_id,
            "--expected-lifecycle-state",
            "active",
        ])
        .expect("parse handoff consume"))
        .expect("consume handoff");
        assert_eq!(value(&consumed, "record_kind"), "handoff");
        assert_eq!(value(&consumed, "handoff_scope_recognized"), "true");
        assert_eq!(value(&consumed, "session_id"), session_id);
        assert_eq!(value(&consumed, "focus_entity_id"), task_id);
        assert_eq!(value(&consumed, "consume_result"), "focus_set");
        assert_eq!(
            value(&consumed, "consume_session_id"),
            continuation_session_id
        );
        assert_eq!(value(&consumed, "consume_lifecycle_state"), "active");
        assert_eq!(value(&consumed, "consume_focus_entity_id"), task_id);
        assert_eq!(value(&consumed, "consume_focus_matches_handoff"), "true");
        assert_eq!(value(&consumed, "source_session_matches_expected"), "true");
        assert_eq!(value(&consumed, "session_diff_matches_expected"), "true");
        assert_eq!(value(&consumed, "focus_matches_expected"), "true");
        assert_eq!(value(&consumed, "consume_session_matches_expected"), "true");
        assert_eq!(
            value(&consumed, "consume_lifecycle_state_matches_expected"),
            "true"
        );

        let continuation_context = run(Cli::try_parse_from([
            "workvcs",
            "context",
            store,
            "--session",
            &continuation_session_id,
        ])
        .expect("parse continuation context"))
        .expect("read continuation context");
        assert_eq!(value(&continuation_context, "focus_entity_id"), task_id);

        let mismatched_focus = run(Cli::try_parse_from([
            "workvcs",
            "handoff",
            "show",
            store,
            "--commit",
            &handoff_commit,
            "--handoff",
            &handoff_id,
            "--expected-focus",
            "none",
        ])
        .expect("parse mismatched handoff show"));
        assert!(mismatched_focus.is_err());
    }

    #[test]
    fn cli_runs_claim_next_workflow() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let mut head = value(&workspace, "genesis_commit_id");

        let first = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--description",
            "First CLI next task",
        ])
        .expect("parse first task"))
        .expect("create first task");
        head = value(&first, "commit_id");
        let second = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--description",
            "Second CLI next task",
        ])
        .expect("parse second task"))
        .expect("create second task");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let claimed =
            run(
                Cli::try_parse_from(["workvcs", "claim", "next", store, "--session", &session_id])
                    .expect("parse claim next"),
            )
            .expect("claim next");
        assert_eq!(value(&claimed, "selected"), "true");
        assert!(claimed.contains("claim_id="));
        assert!(claimed.contains("lifecycle_state=active"));
        assert!(!claimed.contains("claim_next_context_packet="));
        let selected_task = value(&claimed, "task_entity_id");
        assert!(
            selected_task == value(&first, "task_entity_id")
                || selected_task == value(&second, "task_entity_id")
        );

        let runnable = run(Cli::try_parse_from([
            "workvcs",
            "runnable",
            "tasks",
            store,
            "--session",
            &session_id,
        ])
        .expect("parse runnable"))
        .expect("runnable after claim next");
        assert!(runnable.contains(&format!("candidate.0.task_entity_id={selected_task}")));
        assert!(runnable.contains("candidate.0.claim=claimed_by_session:"));

        let limited_runnable = run(Cli::try_parse_from([
            "workvcs",
            "runnable",
            "tasks",
            store,
            "--session",
            &session_id,
            "--limit",
            "1",
        ])
        .expect("parse limited runnable"))
        .expect("limited runnable after claim next");
        assert_eq!(value(&limited_runnable, "candidates"), "1");
        assert!(limited_runnable.contains(&format!("candidate.0.task_entity_id={selected_task}")));

        let zero_limit = run(Cli::try_parse_from([
            "workvcs",
            "runnable",
            "tasks",
            store,
            "--session",
            &session_id,
            "--limit",
            "0",
        ])
        .expect("parse zero-limit runnable"));
        assert!(zero_limit.is_err());
    }

    #[test]
    fn cli_claim_next_can_return_budgeted_context_packet() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");
        let task = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--description",
            "Claim next with packet task",
        ])
        .expect("parse task"))
        .expect("create task");
        let task_id = value(&task, "task_entity_id");
        let task_head = value(&task, "commit_id");
        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let zero_budget = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "next",
            store,
            "--session",
            &session_id,
            "--context-budget-items",
            "0",
        ])
        .expect("parse zero context budget claim next"));
        assert!(matches!(
            zero_budget,
            Err(WorkVcsError::QueryInvalid(message))
                if message == "context budget items must be greater than zero"
        ));

        let claimed = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "next",
            store,
            "--session",
            &session_id,
            "--context-profile",
            "brief",
            "--context-budget-items",
            "3",
            "--context-scope-json",
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}",
            "--expected-selected",
            "true",
            "--expected-head",
            &task_head,
            "--expected-task",
            &task_id,
            "--expected-mode",
            "exclusive",
            "--expected-lifecycle-state",
            "active",
        ])
        .expect("parse claim next with context packet"))
        .expect("claim next with context packet");
        assert_eq!(value(&claimed, "selected"), "true");
        assert_eq!(value(&claimed, "task_entity_id"), task_id);
        assert_eq!(value(&claimed, "claim_next_context_packet"), "true");
        assert_eq!(value(&claimed, "claim_next_session_id"), session_id);
        assert_eq!(value(&claimed, "claim_next_focus_entity_id"), task_id);
        assert_eq!(value(&claimed, "claim_next_context_profile"), "brief");
        assert_eq!(value(&claimed, "claim_next_context_budget_items"), "3");
        assert_eq!(
            value(&claimed, "claim_next_context_scope_json"),
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}"
        );
        assert_eq!(value(&claimed, "claim_next_context_items"), "3");
        assert_eq!(value(&claimed, "claim_next_context_omitted_items"), "1");
        assert_eq!(
            value(&claimed, "claim_next_context_item.0.category"),
            "session_anchor"
        );
        assert_eq!(
            value(&claimed, "claim_next_context_item.1.category"),
            "branch_overview"
        );
        assert_eq!(
            value(&claimed, "claim_next_context_item.2.category"),
            "current_task"
        );
        assert_eq!(value(&claimed, "selected_match_expected"), "true");
        assert_eq!(value(&claimed, "head_match_expected"), "true");
        assert_eq!(value(&claimed, "task_match_expected"), "true");
        assert_eq!(value(&claimed, "mode_match_expected"), "true");
        assert_eq!(value(&claimed, "lifecycle_state_match_expected"), "true");
    }

    #[test]
    fn cli_runs_claim_transfer_and_force_takeover_workflow() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let genesis = value(&workspace, "genesis_commit_id");

        let task = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &genesis,
            "--description",
            "Claim replacement task",
        ])
        .expect("parse task"))
        .expect("create task");
        let task_id = value(&task, "task_entity_id");

        let first_session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse first session start"))
        .expect("start first session");
        let first_session_id = value(&first_session, "session_id");
        let second_session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse second session start"))
        .expect("start second session");
        let second_session_id = value(&second_session, "session_id");
        let third_session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse third session start"))
        .expect("start third session");
        let third_session_id = value(&third_session, "session_id");

        let first_claim = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "task",
            store,
            "--session",
            &first_session_id,
            "--task",
            &task_id,
            "--expected-mode",
            "exclusive",
            "--expected-lifecycle-state",
            "active",
        ])
        .expect("parse claim task"))
        .expect("claim task");
        let first_claim_id = value(&first_claim, "claim_id");

        let blocked_guard = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "guard",
            store,
            "--session",
            &second_session_id,
            "--task",
            &task_id,
            "--expected-allowed",
            "false",
            "--expected-reason",
            "exclusive_claim_owned_by_other_session",
            "--expected-active-claims",
            "1",
        ])
        .expect("parse blocked guard"))
        .expect("blocked guard");
        assert_eq!(value(&blocked_guard, "allowed_match_expected"), "true");
        assert_eq!(value(&blocked_guard, "reason_match_expected"), "true");

        let transferred = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "transfer",
            store,
            "--from-session",
            &first_session_id,
            "--to-session",
            &second_session_id,
            "--claim",
            &first_claim_id,
            "--expected-previous-claim",
            &first_claim_id,
            "--expected-from-session",
            &first_session_id,
            "--expected-to-session",
            &second_session_id,
            "--expected-mode",
            "exclusive",
            "--expected-lifecycle-state",
            "active",
        ])
        .expect("parse claim transfer"))
        .expect("transfer claim");
        let second_claim_id = value(&transferred, "claim_id");
        assert_ne!(second_claim_id, first_claim_id);
        assert_eq!(value(&transferred, "previous_claim_id"), first_claim_id);
        assert_eq!(value(&transferred, "from_session_id"), first_session_id);
        assert_eq!(value(&transferred, "to_session_id"), second_session_id);
        assert_eq!(value(&transferred, "previous_lifecycle_state"), "released");
        assert_eq!(value(&transferred, "lifecycle_state"), "active");
        assert_eq!(value(&transferred, "previous_claim_match_expected"), "true");
        assert_eq!(
            value(&transferred, "previous_session_match_expected"),
            "true"
        );
        assert_eq!(value(&transferred, "session_match_expected"), "true");
        assert_eq!(value(&transferred, "mode_match_expected"), "true");
        assert_eq!(
            value(&transferred, "lifecycle_state_match_expected"),
            "true"
        );

        let old_claim = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "show",
            store,
            "--claim",
            &first_claim_id,
            "--expected-lifecycle-state",
            "released",
        ])
        .expect("parse old claim show"))
        .expect("show old claim");
        assert_eq!(
            value(&old_claim, "lifecycle_state_matches_expected"),
            "true"
        );

        let transferred_guard = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "guard",
            store,
            "--session",
            &second_session_id,
            "--task",
            &task_id,
            "--expected-allowed",
            "true",
            "--expected-reason",
            "owned_exclusive_claim",
            "--expected-active-claims",
            "1",
        ])
        .expect("parse transferred guard"))
        .expect("transferred guard");
        assert_eq!(value(&transferred_guard, "allowed_match_expected"), "true");
        assert_eq!(value(&transferred_guard, "reason_match_expected"), "true");

        let missing_force = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "takeover",
            store,
            "--session",
            &third_session_id,
            "--claim",
            &second_claim_id,
            "--rationale",
            "operator recovery",
        ])
        .expect("parse takeover without force"));
        assert!(missing_force.is_err());

        let active_owner_takeover = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "takeover",
            store,
            "--session",
            &third_session_id,
            "--claim",
            &second_claim_id,
            "--force",
            "--rationale",
            "operator recovery",
        ])
        .expect("parse active-owner takeover"));
        assert!(active_owner_takeover.is_err());

        let marked_stale = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "mark-stale",
            store,
            "--session",
            &second_session_id,
            "--rationale",
            "operator recovery: previous session cannot continue",
            "--expected-session",
            &second_session_id,
            "--expected-lifecycle-state",
            "potentially_stale",
        ])
        .expect("parse mark stale"))
        .expect("mark previous session stale");
        assert_eq!(value(&marked_stale, "lifecycle_state"), "potentially_stale");

        let taken_over = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "takeover",
            store,
            "--session",
            &third_session_id,
            "--claim",
            &second_claim_id,
            "--force",
            "--rationale",
            "operator recovery",
            "--expected-previous-claim",
            &second_claim_id,
            "--expected-previous-session",
            &second_session_id,
            "--expected-previous-session-lifecycle-state",
            "potentially_stale",
            "--expected-session",
            &third_session_id,
            "--expected-mode",
            "exclusive",
            "--expected-lifecycle-state",
            "active",
        ])
        .expect("parse claim takeover"))
        .expect("force takeover claim");
        let third_claim_id = value(&taken_over, "claim_id");
        assert_ne!(third_claim_id, second_claim_id);
        assert_eq!(value(&taken_over, "previous_claim_id"), second_claim_id);
        assert_eq!(value(&taken_over, "previous_session_id"), second_session_id);
        assert_eq!(
            value(&taken_over, "previous_session_lifecycle_state"),
            "potentially_stale"
        );
        assert_eq!(value(&taken_over, "session_id"), third_session_id);
        assert_eq!(value(&taken_over, "rationale"), "operator recovery");
        assert_eq!(value(&taken_over, "previous_lifecycle_state"), "released");
        assert_eq!(value(&taken_over, "lifecycle_state"), "active");
        assert_eq!(value(&taken_over, "previous_claim_match_expected"), "true");
        assert_eq!(
            value(&taken_over, "previous_session_match_expected"),
            "true"
        );
        assert_eq!(
            value(
                &taken_over,
                "previous_session_lifecycle_state_match_expected"
            ),
            "true"
        );
        assert_eq!(value(&taken_over, "session_match_expected"), "true");
        assert_eq!(value(&taken_over, "mode_match_expected"), "true");
        assert_eq!(value(&taken_over, "lifecycle_state_match_expected"), "true");

        let released_second_claim = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "show",
            store,
            "--claim",
            &second_claim_id,
            "--expected-lifecycle-state",
            "released",
        ])
        .expect("parse released second claim show"))
        .expect("show released second claim");
        assert_eq!(
            value(&released_second_claim, "lifecycle_state_matches_expected"),
            "true"
        );

        let final_guard = run(Cli::try_parse_from([
            "workvcs",
            "claim",
            "guard",
            store,
            "--session",
            &third_session_id,
            "--task",
            &task_id,
            "--expected-allowed",
            "true",
            "--expected-reason",
            "owned_exclusive_claim",
            "--expected-active-claims",
            "1",
        ])
        .expect("parse final guard"))
        .expect("final guard");
        assert_eq!(value(&final_guard, "allowed_match_expected"), "true");
        assert_eq!(value(&final_guard, "reason_match_expected"), "true");
    }

