        assert!(listed_ids.contains(&resource_id));
        assert!(listed_ids.contains(&second_resource_id));

        let mismatched_resources = run(Cli::try_parse_from([
            "workvcs",
            "resource",
            "list",
            store,
            "--expected-resources",
            "1",
        ])
        .expect("parse mismatched resource list"));
