    #[test]
    fn cli_context_includes_current_active_knowledge_summary() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");

        let active = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--statement",
            "Serialized writes make SQLite sufficient for V0.1",
            "--scope-json",
            "{\"kind\":\"workspace\"}",
        ])
        .expect("parse active knowledge"))
        .expect("create active knowledge");
        let stale = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&active, "commit_id"),
            "--statement",
            "Legacy cache keys do not need schema versions",
        ])
        .expect("parse stale knowledge"))
        .expect("create stale knowledge");
        let invalidated = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "invalidate",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&stale, "commit_id"),
            "--knowledge",
            &value(&stale, "knowledge_entity_id"),
            "--knowledge-version",
            &value(&stale, "knowledge_entity_version_id"),
            "--rationale",
            "Schema versions are part of cache keys",
        ])
        .expect("parse invalidate knowledge"))
        .expect("invalidate knowledge");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let context =
            run(
                Cli::try_parse_from(["workvcs", "context", store, "--session", &session_id])
                    .expect("parse context"),
            )
            .expect("context overview");
        assert_eq!(
            value(&context, "head_commit_id"),
            value(&invalidated, "commit_id")
        );
        assert_eq!(value(&context, "knowledge"), "1");
        assert_eq!(
            value(&context, "context_knowledge.0.knowledge_entity_id"),
            value(&active, "knowledge_entity_id")
        );
        assert!(context.contains(
            "context_knowledge.0.knowledge_statement_json=\"Serialized writes make SQLite sufficient for V0.1\""
        ));
        assert!(
            context.contains("context_knowledge.0.knowledge_scope_json={\"kind\":\"workspace\"}")
        );
        assert!(!context.contains("Legacy cache keys do not need schema versions"));
    }

    #[test]
    fn cli_context_packet_filters_path_scoped_knowledge_by_scope_json() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");

        let matching = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--statement",
            "Matching path knowledge remains visible",
            "--scope-json",
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}",
        ])
        .expect("parse matching knowledge"))
        .expect("create matching knowledge");
        let unrelated = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&matching, "commit_id"),
            "--statement",
            "Unrelated path knowledge is filtered",
            "--scope-json",
            "{\"path\":\"crates/workvcs-cli/src/main.rs\"}",
        ])
        .expect("parse unrelated knowledge"))
        .expect("create unrelated knowledge");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let context = run(Cli::try_parse_from([
            "workvcs",
            "context",
            store,
            "--session",
            &session_id,
            "--scope-json",
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}",
        ])
        .expect("parse scoped packet context"))
        .expect("scoped packet context");

        assert_eq!(
            value(&context, "head_commit_id"),
            value(&unrelated, "commit_id")
        );
        assert_eq!(value(&context, "context_profile"), "normal");
        assert_eq!(value(&context, "context_budget_items"), "none");
        assert_eq!(
            value(&context, "context_scope_json"),
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}"
        );
        assert!(context.contains("Matching path knowledge remains visible"));
        assert!(!context.contains("Unrelated path knowledge is filtered"));

        let shorthand_context = run(Cli::try_parse_from([
            "workvcs",
            "context",
            store,
            "--session",
            &session_id,
            "--scope-path",
            "crates/workvcs-core/src/./runtime/context.rs",
        ])
        .expect("parse shorthand scoped packet context"))
        .expect("shorthand scoped packet context");
        assert_eq!(
            value(&shorthand_context, "context_scope_json"),
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}"
        );
        assert!(shorthand_context.contains("Matching path knowledge remains visible"));
        assert!(!shorthand_context.contains("Unrelated path knowledge is filtered"));
    }

    #[test]
    fn cli_context_packet_accepts_path_scope_shorthands() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");
        let project = tempdir.path().join("project");
        let matching_path = project.join("src").join("..").join("src").join("lib.rs");
        let context_path = project.join("src").join(".").join("lib.rs");
        let expected_path = project.join("src").join("lib.rs");
        let unrelated_path = project.join("tests").join("lib.rs");
        let prefix_path = project.join("src").join(".");
        let matching_path = matching_path.to_str().expect("matching path text");
        let context_path = context_path.to_str().expect("context path text");
        let expected_path = expected_path.to_str().expect("expected path text");
        let unrelated_path = unrelated_path.to_str().expect("unrelated path text");
        let prefix_path = prefix_path.to_str().expect("prefix path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");

        let matching = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--statement",
            "Path shorthand knowledge remains visible",
            "--scope-path",
            matching_path,
        ])
        .expect("parse matching knowledge"))
        .expect("create matching knowledge");
        let unrelated = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&matching, "commit_id"),
            "--statement",
            "Path shorthand unrelated knowledge is filtered",
            "--scope-path",
            unrelated_path,
        ])
        .expect("parse unrelated knowledge"))
        .expect("create unrelated knowledge");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let context = run(Cli::try_parse_from([
            "workvcs",
            "context",
            store,
            "--session",
            &session_id,
            "--scope-path",
            context_path,
        ])
        .expect("parse scoped packet context"))
        .expect("scoped packet context");

        assert_eq!(
            value(&context, "head_commit_id"),
            value(&unrelated, "commit_id")
        );
        assert_eq!(
            value(&context, "context_scope_json"),
            format!(r#"{{"path":"{expected_path}"}}"#)
        );
        assert!(context.contains("Path shorthand knowledge remains visible"));
        assert!(!context.contains("Path shorthand unrelated knowledge is filtered"));

        let saved = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "save",
            store,
            "--session",
            &session_id,
            "--scope-path-prefix",
            prefix_path,
        ])
        .expect("parse scoped packet save"))
        .expect("save scoped packet");
        assert_eq!(
            value(&saved, "context_scope_json"),
            format!(r#"{{"path_prefix":"{}"}}"#, project.join("src").display())
        );
        assert_eq!(value(&saved, "saved_context_items"), "4");
    }

