    #[test]
    fn cli_context_packet_projects_transition_rationale() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");

        let goal = run(Cli::try_parse_from([
            "workvcs",
            "goal",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--description",
            "Close transition rationale projection",
        ])
        .expect("parse goal"))
        .expect("create goal");
        let achieved = run(Cli::try_parse_from([
            "workvcs",
            "goal",
            "achieve",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&goal, "commit_id"),
            "--goal",
            &value(&goal, "goal_entity_id"),
            "--goal-version",
            &value(&goal, "goal_entity_version_id"),
            "--rationale",
            "transition rationale is needed for continuation",
        ])
        .expect("parse goal achieve"))
        .expect("achieve goal");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let context = run(Cli::try_parse_from([
            "workvcs",
            "context",
            store,
            "--session",
            &session_id,
            "--profile",
            "brief",
            "--budget-items",
            "3",
        ])
        .expect("parse context packet"))
        .expect("context packet");

        assert_eq!(
            value(&context, "head_commit_id"),
            value(&achieved, "commit_id")
        );
        assert_eq!(value(&context, "context_profile"), "brief");
        assert_eq!(value(&context, "context_available_items"), "3");
        assert_eq!(value(&context, "context_items"), "3");
        assert_eq!(
            value(&context, "context_item.2.category"),
            "transition_rationale"
        );
        assert_eq!(
            value(&context, "context_item.2.subject"),
            format!(
                "changeset:{}@{}",
                value(&achieved, "changeset_id"),
                value(&achieved, "commit_id")
            )
        );
        assert!(context.contains("operation=entity.transition"));
        assert!(context.contains("transition rationale is needed for continuation"));

        let saved = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "save",
            store,
            "--session",
            &session_id,
            "--profile",
            "brief",
            "--budget-items",
            "3",
        ])
        .expect("parse context packet save"))
        .expect("save context packet");
        let shown = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "show",
            store,
            "--packet",
            &value(&saved, "context_packet_id"),
        ])
        .expect("parse context packet show"))
        .expect("show context packet");
        assert_eq!(value(&saved, "context_items"), "3");
        assert!(value(&shown, "packet_json").contains("transition_rationale"));
        assert!(
            value(&shown, "packet_json")
                .contains("transition rationale is needed for continuation")
        );
    }

    #[test]
    fn cli_saves_shows_and_lists_context_packet_snapshots() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");

        let task = run(Cli::try_parse_from([
            "workvcs",
            "task",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--description",
            "Save an inspectable context packet",
        ])
        .expect("parse task"))
        .expect("create task");
        let matching = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&task, "commit_id"),
            "--statement",
            "CLI persisted packet keeps matching path",
            "--scope-json",
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}",
        ])
        .expect("parse matching knowledge"))
        .expect("create matching knowledge");
        let unrelated = run(Cli::try_parse_from([
            "workvcs",
            "knowledge",
            "create",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&matching, "commit_id"),
            "--statement",
            "CLI persisted packet filters other path",
            "--scope-json",
            "{\"path\":\"crates/workvcs-cli/src/main.rs\"}",
        ])
        .expect("parse unrelated knowledge"))
        .expect("create unrelated knowledge");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let saved = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "save",
            store,
            "--session",
            &session_id,
            "--profile",
            "normal",
            "--budget-items",
            "8",
            "--scope-json",
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}",
        ])
        .expect("parse context packet save"))
        .expect("save context packet");
        let packet_id = value(&saved, "context_packet_id");
        let packet_digest = value(&saved, "packet_digest");
        assert_eq!(value(&saved, "session_id"), session_id);
        assert_eq!(value(&saved, "branch_id"), branch);
        assert_eq!(
            value(&saved, "head_commit_id"),
            value(&unrelated, "commit_id")
        );
        assert_eq!(value(&saved, "context_profile"), "normal");
        assert_eq!(value(&saved, "context_budget_items"), "8");
        assert_eq!(
            value(&saved, "context_scope_json"),
            "{\"path\":\"crates/workvcs-core/src/runtime/context.rs\"}"
        );
        assert_eq!(
            value(&saved, "saved_context_items"),
            value(&saved, "context_items")
        );

        let shown = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "show",
            store,
            "--packet",
            &packet_id,
        ])
        .expect("parse context packet show"))
        .expect("show context packet");
        assert_eq!(value(&shown, "context_packet_id"), packet_id);
        assert_eq!(value(&shown, "packet_digest"), packet_digest);
        assert_eq!(
            value(&shown, "context_scope_json"),
            value(&saved, "context_scope_json")
        );
        let packet_json = value(&shown, "packet_json");
        assert!(packet_json.contains("\"context_packet_format\":\"workvcs-context-packet-v1\""));
        assert!(packet_json.contains("CLI persisted packet keeps matching path"));
        assert!(!packet_json.contains("CLI persisted packet filters other path"));

        let listed = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "list",
            store,
            "--session",
            &session_id,
            "--expected-packets",
            "1",
        ])
        .expect("parse context packet list"))
        .expect("list context packets");
        assert_eq!(value(&listed, "context_packets"), "1");
        assert_eq!(value(&listed, "context_packets_match_expected"), "true");
        assert_eq!(
            value(&listed, "context_packet.0.context_packet_id"),
            packet_id
        );
        assert_eq!(
            value(&listed, "context_packet.0.packet_digest"),
            packet_digest
        );

        let zero_limit = run(Cli::try_parse_from([
            "workvcs",
            "context-packet",
            "list",
            store,
            "--session",
            &session_id,
            "--limit",
            "0",
        ])
        .expect("parse zero context packet list limit"));
        assert!(matches!(
            zero_limit,
            Err(WorkVcsError::QueryInvalid(message))
                if message == "context packet list limit must be greater than zero"
        ));
    }

    #[test]
    fn cli_context_includes_current_record_relation_summary() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let path = tempdir.path().join("workvcs.sqlite");
        let store = path.to_str().expect("path text");

        run(
            Cli::try_parse_from(["workvcs", "init", store, "--display-name", "cli-store"])
                .expect("parse init"),
        )
        .expect("run init");
        let workspace = run(Cli::try_parse_from([
            "workvcs",
            "workspace",
            "create",
            store,
            "--display-name",
            "workspace",
        ])
        .expect("parse workspace"))
        .expect("create workspace");
        let workspace_id = value(&workspace, "workspace_id");
        let branch = value(&workspace, "branch_id");
        let head = value(&workspace, "genesis_commit_id");

        let decision = run(Cli::try_parse_from([
            "workvcs",
            "record",
            "decision",
            store,
            "--branch",
            &branch,
            "--head",
            &head,
            "--statement",
            "Use serialized writes",
        ])
        .expect("parse decision"))
        .expect("create decision");
        let finding = run(Cli::try_parse_from([
            "workvcs",
            "record",
            "finding",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&decision, "commit_id"),
            "--statement",
            "Benchmarks support serialized writes",
        ])
        .expect("parse finding"))
        .expect("create finding");
        let relation = run(Cli::try_parse_from([
            "workvcs",
            "record",
            "link-supports",
            store,
            "--branch",
            &branch,
            "--head",
            &value(&finding, "commit_id"),
            "--source-record",
            &value(&finding, "record_entity_id"),
            "--target-record",
            &value(&decision, "record_entity_id"),
            "--rationale",
            "Finding supports the decision",
        ])
        .expect("parse link supports"))
        .expect("link supports");

        let session = run(Cli::try_parse_from([
            "workvcs",
            "session",
            "start",
            store,
            "--workspace",
            &workspace_id,
            "--branch",
            &branch,
        ])
        .expect("parse session start"))
        .expect("start session");
        let session_id = value(&session, "session_id");

        let context =
            run(
                Cli::try_parse_from(["workvcs", "context", store, "--session", &session_id])
                    .expect("parse context"),
            )
            .expect("context overview");
        assert!(context.contains("records=2"));
        assert!(context.contains("record_relations=1"));
        assert_eq!(
            value(&context, "context_record_relation.0.relation_id"),
            value(&relation, "relation_id")
        );
        assert!(context.contains("context_record_relation.0.relation_type=supports"));
        assert_eq!(
            value(
                &context,
                "context_record_relation.0.source_record_entity_id"
            ),
            value(&finding, "record_entity_id")
        );
        assert_eq!(
            value(
                &context,
                "context_record_relation.0.target_record_entity_id"
            ),
            value(&decision, "record_entity_id")
        );
    }

